    private final Runnable foregroundPoll = new Runnable() {
        @Override
        public void run() {
            if (!prefs.getBoolean("enabled", false)) return;

            try {
                boolean observerPermissionsReady = validateObserverRuntimePermissions();
            if (observerPermissionsReady) refreshForegroundPackage();
            long now = System.currentTimeMillis();
            persistServiceHeartbeatIfDue(now);
            // HF64: a certified terminal delivery is already proven. Progress its local
            // persistence/queue state before consulting volatile foreground ownership so
            // UsageStats lag can never leave the driver on the completed-trip card.
            recoverTerminalProgressIfNeeded(now);
            reconcileProjectionPermissionLifecycle(now);
            // A granted token may be waiting for the GTO to return in landscape. This
            // check runs independently of UsageStats so an explicit NVU->GTO launch can
            // still bootstrap the surface on OEMs whose foreground event arrives late.
            maybeStartPendingProjectionSurface(now);
            maybeForceReturnSurfaceRefresh(now);
            maybeRecoverProjectionFrameDelivery(now);
            // ACK reconciliation is durable-state work, not foreground/UI work. Run it
            // before the rawGto branch so leaving GTO for WhatsApp cannot leave a confirmed
            // delivery in RESULT_CONFIRMED and make the next freight invisible on return.
            reconcileAcknowledgedTripForNextFreight();
            expireBubbleGestureIfStale(now);

            // OEMs can detach an overlay without throwing through our original addView().
            // Treat a detached bubble as absent so the existing retry path can restore it.
            if (bubbleView != null && !bubbleView.isAttachedToWindow()) {
                cancelBubbleGesture("BUBBLE_DETACHED", true);
                clearBubbleReferenceAndRemove("BUBBLE_DETACHED");
                // R3.10: a detached OEM overlay is treated as an immediate recovery event.
                // Reset the throttle so this same foreground poll can recreate the bubble
                // instead of waiting a full retry interval on slower devices.
                lastBubbleAttemptAt = 0L;
                prefs.edit()
                    .putBoolean("overlayVisible", false)
                    .putString("lastEvent", "Botão flutuante foi desconectado pelo Android; restaurando")
                    .apply();
            }

            boolean visualGtoProofFresh = lastVisualGtoForegroundEvidenceAt > 0L
                && now >= lastVisualGtoForegroundEvidenceAt
                && now - lastVisualGtoForegroundEvidenceAt <= VISUAL_GTO_EVIDENCE_FRESH_MS;
            boolean packageMatchesGto = GTO_PACKAGE.equals(foregroundPackage);
            boolean packageUnknown = foregroundPackage == null || foregroundPackage.isEmpty();
            boolean ownPermissionReturnBridge = now < suppressForegroundHideUntil
                && getPackageName().equals(foregroundPackage);
            boolean visualBridgeAllowed = visualGtoProofFresh
                && (packageUnknown || ownPermissionReturnBridge);
            boolean verifiedProjectionBridgeAllowed = GtoProjectionForegroundBridgePolicy.allow(
                projectionVerifiedGtoBridgeActive,
                transientForegroundSurfaceActive,
                packageMatchesGto,
                packageUnknown,
                getPackageName().equals(foregroundPackage),
                nvuMainActivityForeground
            );
            if (transientForegroundSurfaceActive
                && gtoForeground
                && transientForegroundSurfaceAt > 0L
                && now - transientForegroundSurfaceAt >= TRANSIENT_OVERLAY_STALE_RECOVERY_MS
                && (packageMatchesGto || visualBridgeAllowed || verifiedProjectionBridgeAllowed)) {
                // Fail-open only to ANALYSIS, never to data acceptance: every screen/freight
                // still has to pass its ordinary visual + OCR consensus gates. This repairs
                // OEMs that omit the transient-surface background event and would otherwise
                // leave the observer paused indefinitely.
                transientForegroundSurfaceActive = false;
                transientForegroundPackage = "";
                transientForegroundSurfaceAt = now;
                prefs.edit()
                    .putString("lastEvent", "Interface temporária sem evento de retorno · retomando leitura protegida")
                    .apply();
            }

            // HF89: projection/permission bridges keep transport recovery alive but are not
            // foreground ownership. Only the exact GTO package or a fresh strict visual proof
            // may promote the UI context. This prevents a stale bridge from hiding the outside
            // remove target and from making the health indicator oscillate.
            boolean rawGto = observerPermissionsReady
                && !transientForegroundSurfaceActive
                && (packageMatchesGto || visualGtoProofFresh);

            // HF91 root fix: the previous supervisor promoted gtoForeground=true but
            // never symmetrically demoted it when UsageStats reported a real external
            // owner. That stale flag hid the destructive-drag target and made return
            // reconciliation impossible. Demote only on explicit non-GTO ownership or a
            // newer GTO background event; unknown/transient states preserve transport but
            // do not fabricate a foreground transition.
            boolean knownExternalOwner = !rawGto
                && !transientForegroundSurfaceActive
                && !projectionPermissionInFlight
                && foregroundPackage != null
                && !foregroundPackage.isEmpty()
                && !GTO_PACKAGE.equals(foregroundPackage);
            boolean confirmedGtoBackground = !rawGto
                && !transientForegroundSurfaceActive
                && !visualGtoProofFresh
                && lastGtoBackgroundEventAt > lastGtoForegroundEventAt;
            if ((knownExternalOwner || confirmedGtoBackground) && gtoForeground) {
                gtoForeground = false;
                nonGtoForegroundSince = nonGtoForegroundSince > 0L
                    ? nonGtoForegroundSince : now;
                pauseScreenAnalysisOutsideGto("GTO_EXIT_CONFIRMED_BY_FOREGROUND_OWNER");
                prefs.edit()
                    .putBoolean("gtoForeground", false)
                    .putLong("gtoBackgroundContextAt", now)
                    .putString("gtoBackgroundContextSource", knownExternalOwner
                        ? "USAGE_STATS_EXTERNAL_OWNER" : "GTO_BACKGROUND_EVENT")
                    .putBoolean("touchCaptureNeeded", false)
                    .putString("lastEvent", "GTO saiu do primeiro plano · captura preservada e botão externo habilitado")
                    .apply();
                suspendPassiveDetectionOverlaysKeepBubbleAndMenu();
            }

            if (rawGto) {
                // Never cancel an explicit outside-GTO drag merely because UsageStats/bridge
                // changed during the gesture. The release policy validates the same gesture
                // generation and the target geometry before stopping the observer.
                if (!bubbleGestureActive) disarmBubbleStopForCurrentGesture("GTO_FOREGROUND");
                long absenceMs = nonGtoForegroundSince > 0L ? now - nonGtoForegroundSince : 0L;
                lastGtoForegroundEvidenceAt = now;
                nonGtoForegroundSince = 0L;
                if (!gtoForeground) {
                    gtoForeground = true;
                    prefs.edit().putBoolean("gtoForeground", true).apply();
                    playGtoAutomatedStartVoiceIfEligible(now);
                }
                resumeScreenAnalysisInSameState(absenceMs);

                // HF3 ordering invariant: establish/repair the TYPE_APPLICATION_OVERLAY
                // token while GTO is unquestionably foreground BEFORE launching the
                // MediaProjection consent surface. Permission UI is transient and must
                // never be allowed to suppress the main recovery control.
                if (bubbleView == null
                    && now - lastBubbleAttemptAt >= BUBBLE_RETRY_INTERVAL_MS) {
                    showBubbleIfAllowed();
                } else if (bubbleView != null && !bubbleView.isAttachedToWindow()) {
                    // Defensive stale-token recovery: an OEM can keep a Java reference after
                    // detaching the underlying overlay window. Remove it and retry immediately.
                    clearBubbleReferenceAndRemove("BUBBLE_DETACHED_FOREGROUND_RETRY");
                    showBubbleIfAllowed();
                }
                // If the bubble survived a portrait/system-app interval, restore the
                // driver's normalized landscape anchor as soon as the GTO geometry is
                // stable. This happens before consent/recovery UI can take input focus.
                reconcileBubbleForStableGtoGeometry(now);

                // Only after the bubble had a chance to attach may the recorder consent
                // be opened. maybeLaunchInitialProjectionPermissionOverGto() enforces
                // the attached-window precondition too, so slow OEM WindowManager paths
                // simply retry on the next foreground poll instead of racing the bubble.
                maybeLaunchInitialProjectionPermissionOverGto(now);
                retryPendingDriverStageIfNeeded(now);
                recoverUnsealedCompletedTripIfNeeded(now);
                recoverSealedCompletionToWaitingIfNeeded();
                updateFreightTouchPulseSensor();
                ensureProjectionAuthorizationIfNeeded(now);
                enforceOperationalReadiness(now, observerPermissionsReady);
            } else if (transientForegroundSurfaceActive && gtoForeground) {
                // Do not destroy/recreate the main floating bubble for notification shade,
                // permission controller or OEM game-assistant surfaces. The capture session
                // remains the analysis authority; only overlay placement is suspended.
                keepFrameAnalysisSessionActive(now, "TRANSIENT_SURFACE_CAPTURE_SESSION");
                suspendPassiveDetectionOverlaysKeepBubbleAndMenu();
                if (now - transientForegroundSurfaceAt >= TRANSIENT_OVERLAY_DIAGNOSTIC_GRACE_MS) {
                    prefs.edit()
                        .putString("lastEvent", "Interface temporária sobre o GTO · sessão de captura preservada")
                        .apply();
                }
            } else if (isFrameAnalysisSessionActive()) {
                // HF86: a stale/missing foreground event must not pause a live authorized
                // analysis session. Keep the capture and detector armed; only semantic
                // recognition is allowed to decide what the current pixels mean.
                keepFrameAnalysisSessionActive(now, "LIVE_CAPTURE_CONTINUITY");
                prefs.edit()
                    .putString("lastEvent", "Sessão de captura contínua · detector mantido ativo sem prova externa")
                    .apply();
            } else {
                keepFrameAnalysisSessionActive(now, "FOREGROUND_UNKNOWN_CAPTURE_SESSION");
                // Keep the primary NVU bubble attached for the whole automatic session.
                // Transient SystemUI surfaces are handled in the branch above and never
                // minimize the card. A positively identified third-party app may minimize
                // the card only after sustained background evidence; the bubble/state stay
                // alive and the card can be reopened immediately on return.
                if (shouldMinimizeMenuForConfirmedExternalApp(now)) {
                    closeMenu();
                    hideStatusChip();
                    prefs.edit()
                        .putLong("menuMinimizedForExternalAppAt", now)
                        .putString("lastEvent", "Card NVU minimizado após saída confirmada do GTO")
                        .apply();
                }
                suspendPassiveDetectionOverlaysKeepBubbleAndMenu();
            }

            if (!rawGto) enforceOperationalReadiness(now, observerPermissionsReady);
            updateObserverLifecycleStatus(now);
            updateCaptureHealthIndicator(now);

            if (now - lastAutoSyncRetryAt >= AUTO_SYNC_RETRY_INTERVAL_MS && GtoAutoTripSync.hasPending(GtoObserverService.this)) {
                lastAutoSyncRetryAt = now;
                flushAutomaticTripQueue();
            }

            } catch (Exception ex) {
                // The foreground supervisor is the liveness boundary for the whole native
                // observer. A transient UsageStats/WindowManager/OCR-side exception must
                // never terminate the Runnable and leave the service apparently alive but
                // blind. Keep the durable trip untouched and let the next cycle retry.
                recordObserverIncident("SUPERVISOR_EXCEPTION", describeError(ex));
                if (prefs != null) {
                    prefs.edit()
                        .putString("supervisorLastError", describeError(ex))
                        .putLong("supervisorLastErrorAt", System.currentTimeMillis())
                        .putString("lastEvent", "Supervisor do observador rearmado após falha transitória")
                        .apply();
                }
            } finally {
                if (prefs != null && prefs.getBoolean("enabled", false) && !destroying) {
                    mainHandler.removeCallbacks(this);
                    mainHandler.postDelayed(this, FOREGROUND_POLL_INTERVAL_MS);
                }
            }
        }
    };

    public static boolean isRunning() {
        return running;
    }

    public static void refreshOperationCardIfRunning() {
        GtoObserverService live = instance;
        if (live == null || !running || live.destroying) return;
        live.mainHandler.post(() -> {
            if (live.destroying || live.prefs == null) return;
            GtoAutoTripSync.persistOperationContextSnapshot(live, live.prefs);
            GtoAutoTripSync.ensureCurrentOperationSnapshot(live, live.prefs);
            if (live.menuView != null) live.refreshMenuContents();
        });
    }

    /**
     * Single native source of truth for UI/status consumers. A stale SharedPreferences
     * heartbeat cannot keep the detector marked active after GTO return; the live service
     * must prove the strict capture pipeline is healthy at this instant.
     */
    public static boolean isDetectorOperationalNow() {
        GtoObserverService live = instance;
        return live != null && running && !live.destroying
            && live.isDetectorActive(System.currentTimeMillis());
    }

    public static boolean isSelectionCommitContextEligibleNow() {
        GtoObserverService live = instance;
        return live != null && running && !live.destroying
            && live.isConfirmedSelectionCommitContext(System.currentTimeMillis());
    }

    /**
     * Called by the process-wide FirebaseAuth listener. Auth recovery is an event, not a
     * reason to wait for Activity onStart or the 15-second supervisor cadence.
     */
    public static void retryAutomaticTripQueueIfRunning() {
        GtoObserverService live = instance;
        if (live == null || !running || live.destroying) return;
        live.mainHandler.post(() -> {
            if (live.prefs == null || live.destroying) return;
            GtoAutoTripSync.recoverLegacyPendingStateOnAuthenticatedStart(live, live.prefs);
            live.flushAutomaticTripQueue();
        });
    }

    /**
     * Reconciles a server ACK even when the queue was flushed by MainActivity with no
     * listener. The ACK itself is the durable boundary; UI/service ownership must not
     * decide whether the next consecutive freight session is prepared.
     */
    public static void reconcileAcknowledgedTripIfRunning() {
        GtoObserverService live = instance;
        if (live == null || !running || live.destroying) return;
        live.mainHandler.post(() -> {
            if (live.prefs == null || live.destroying) return;
            live.reconcileAcknowledgedTripForNextFreight();
        });
    }

    /**
     * Called immediately before either the Capacitor plugin or MainActivity brings the
     * existing GTO task forward. A projection that was ready for a previous surface is
     * never trusted for the new launch until fresh foreground evidence and stable frames
     * are observed again.
     */
    /**
     * Arms the canonical journey state before the GTO task is brought to foreground.
     *
     * R3.27 root-cause fix: the Web launcher used to open GTO while the native observer
     * was still IDLE. On OEMs with delayed UsageStats this created a circular gate: live
     * freight pixels were only allowed to prove GTO foreground in WAITING_FREIGHT, while
     * reaching WAITING_FREIGHT depended on those same pixels being analyzed. Preparing
     * the session here makes WAITING_FREIGHT authoritative before the first GTO frame.
     * Existing active journeys are preserved exactly as-is.
     */
    public static boolean prepareWorkLaunchIfRunning() {
        GtoObserverService current = instance;
        if (current == null || !running || current.destroying) return false;

        if (Looper.myLooper() == current.mainHandler.getLooper()) {
            return current.prepareJourneyForGtoLaunch();
        }

        CountDownLatch latch = new CountDownLatch(1);
        AtomicBoolean prepared = new AtomicBoolean(false);
        current.mainHandler.post(() -> {
            try {
                prepared.set(current.prepareJourneyForGtoLaunch());
            } finally {
                latch.countDown();
            }
        });
        try {
            return latch.await(1400L, TimeUnit.MILLISECONDS) && prepared.get();
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    private void sanitizeLegacyUntrustedPendingSelectionOnStartup() {
        if (prefs == null) return;
        String state = prefs.getString("tripState", STATE_IDLE);
        String status = prefs.getString("selectionIdentityStatus", "");
        String source = prefs.getString("selectionIdentitySource", prefs.getString("selectionSource", ""));
        boolean hasReview = prefs.getBoolean("pendingFreightReview", false)
            || "REVIEW_REQUIRED".equals(prefs.getString("selectionConfirmationStatus", ""));
        boolean pendingUntrusted = STATE_CONFIRMING_FREIGHT.equals(state)
            && ("CONFIRMED".equals(status) || hasReview)
            && !GtoSelectionEvidencePolicy.isHumanBackedSource(source);
        boolean activeLegacyUntrusted = STATE_TRIP_IN_PROGRESS.equals(state)
            && "CONFIRMED".equals(prefs.getString("selectionConfirmationStatus", ""))
            && !GtoSelectionEvidencePolicy.isHumanBackedSource(source);
        if (!pendingUntrusted && !activeLegacyUntrusted) return;

        if (activeLegacyUntrusted) {
            String unsafeSession = prefs.getString("gtoTripSessionId", "");
            if (!clearTripAnalysis()) return;
            GtoAutoTripSync.discardSessionSnapshot(this, unsafeSession);
            prefs.edit()
                .putString("tripState", STATE_IDLE)
                .putString("lastEvent", "Frete legado sem prova humana descartado · inicie o trabalho novamente")
                .putString("gtoTripIntegrityStatus", "LEGACY_UNTRUSTED_SELECTION_DROPPED")
                .apply();
            recordObserverIncident("LEGACY_UNTRUSTED_ACTIVE_TRIP_DROPPED", "source=" + source);
            return;
        }

        prefs.edit()
            .putString("tripState", STATE_WAITING_FREIGHT)
            .putString("lastEvent", "Seleção antiga sem prova humana descartada · aguardando lista certificada")
            .remove("selectionIdentityStatus")
            .remove("selectionIdentitySource")
            .remove("selectionIdentityAt")
            .remove("selectionConfirmationStatus")
            .remove("pendingFreightReview")
            .remove("reviewRequiredField")
            .remove("selectedFreightRow")
            .remove("preciseSelectedRow")
            .remove("selectedFreight")
            .remove("selectedFreightSummary")
            .remove("reviewCargo")
            .remove("reviewCargoListSameRowAuthority")
            .remove("reviewOrigin")
            .remove("reviewOriginSource")
            .remove("reviewOriginCompany")
            .remove("reviewDestinationCompany")
            .remove("reviewDestination")
            .remove("reviewKm")
            .remove("reviewValue")
            .remove("reviewCargoSource")
            .remove("reviewOriginCompanySource")
            .remove("reviewDestinationCompanySource")
            .remove("reviewDestinationSource")
            .remove("reviewKmSource")
            .remove("reviewValueSource")
            .remove("manualRouteSelectionPending")
            .remove("manualRouteSelectionStep")
            .remove("manualRouteSelectionConfirmed")
            .apply();
        recordObserverIncident("LEGACY_UNTRUSTED_SELECTION_DROPPED", "source=" + source);
    }

    private boolean prepareFreshSessionAfterOperationSwitch(String state) {
        if (!STATE_RESULT_CONFIRMED.equals(state)
            || !prefs.getBoolean("gtoOperationContextChanged", false)) return false;

        String previousSession = prefs.getString("gtoTripSessionId", "").trim();
        if (previousSession.isEmpty()) return false;
        if (!GtoAutoTripSync.hasPendingSession(this, previousSession)
            && "CONFIRMED_NORMAL".equals(prefs.getString("completionStatus", ""))) {
            GtoTripSubmissionCoordinator.submitCompletedTrip(this, prefs, automaticTripSyncListener());
        }
        if (!GtoAutoTripSync.hasPendingSession(this, previousSession)) {
            prefs.edit()
                .putString("lastEvent", "Entrega anterior protegida · selamento local ainda em recuperação")
                .apply();
            armCompletionQueueSealRecovery(previousSession, System.currentTimeMillis());
            return false;
        }
        if (!clearTripAnalysis()) return false;
        GtoAutoTripSync.discardSessionSnapshot(this, previousSession);
        prefs.edit()
            .putString("tripState", STATE_IDLE)
            .putBoolean("gtoOperationContextChanged", false)
            .putString("lastEvent", "Nova operação detectada · entrega anterior segue em envio independente")
            .apply();
        return true;
    }

    private boolean prepareJourneyForGtoLaunch() {
        String state = getTripState();
        if (prepareFreshSessionAfterOperationSwitch(state)) {
            state = getTripState();
        }
        if (STATE_CONFIRMING_FREIGHT.equals(state) && !hasConfirmedSelectionIdentity()) {
            sanitizeLegacyUntrustedPendingSelectionOnStartup();
            state = getTripState();
        }
        if (GtoDeterministicFlowPolicy.shouldPrepareWaitingBeforeGtoOpen(state)) {
            // Do not ask for MediaProjection while NVU is still portrait/foreground.
            // The consent is armed below and displayed only after GTO is confirmed.
            beginTrip(false, false);
            state = getTripState();
        }

        boolean prepared = GtoDeterministicFlowPolicy.isPreparedForGtoOpen(state);
        if (prepared) {
            prefs.edit()
                .putBoolean("gtoWorkLaunchPrepared", true)
                .putString("gtoWorkLaunchPreparedState", state)
                .putLong("gtoWorkLaunchPreparedAt", System.currentTimeMillis())
                .putString("lastEvent", STATE_WAITING_FREIGHT.equals(state)
                    ? "GTO preparado · aguardando lista de fretes"
                    : "GTO preparado · estado da viagem preservado: " + state)
                .apply();
        }
        return prepared;
    }

    /**
     * Rebuilds only volatile overlay views and arms a fresh bubble for the next confirmed
     * GTO foreground. Durable journey/session/freight/result state is deliberately kept.
     * This gives every automatic-mode launch an explicit OEM-safe bubble recovery path.
     */
    public static boolean prepareFloatingButtonForNextGtoLaunch() {
        GtoObserverService current = instance;
        if (current == null || !running || current.destroying) return false;
        if (Looper.myLooper() == current.mainHandler.getLooper()) {
            return current.armFreshFloatingButtonForNextGtoForeground();
        }
        CountDownLatch latch = new CountDownLatch(1);
        AtomicBoolean prepared = new AtomicBoolean(false);
        current.mainHandler.post(() -> {
            try {
                prepared.set(current.armFreshFloatingButtonForNextGtoForeground());
            } finally {
                latch.countDown();
            }
        });
        try {
            return latch.await(1400L, TimeUnit.MILLISECONDS) && prepared.get();
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    /**
     * Idempotent companion used by openGto(). The Web launcher has already called
     * prepareFloatingButton(), so openGto must not immediately tear down the freshly
     * armed/attached overlay a second time. Direct native callers still get the same
     * safety fallback when nothing is currently prepared.
     */
    public static boolean ensureFloatingButtonPreparedForNextGtoLaunch() {
        GtoObserverService current = instance;
        if (current == null || !running || current.destroying) return false;
        if (Looper.myLooper() == current.mainHandler.getLooper()) {
            return current.ensureFloatingButtonPreparedOnMainThread();
        }
        CountDownLatch latch = new CountDownLatch(1);
        AtomicBoolean prepared = new AtomicBoolean(false);
        current.mainHandler.post(() -> {
            try {
                prepared.set(current.ensureFloatingButtonPreparedOnMainThread());
            } finally {
                latch.countDown();
            }
        });
        try {
            return latch.await(1400L, TimeUnit.MILLISECONDS) && prepared.get();
        } catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    private boolean ensureFloatingButtonPreparedOnMainThread() {
        boolean attached = bubbleView != null && bubbleView.isAttachedToWindow();
        boolean armed = prefs != null && prefs.getBoolean("floatingButtonActivationArmed", false);
        if (attached || armed) return true;
        return armFreshFloatingButtonForNextGtoForeground();
    }

    private boolean armFreshFloatingButtonForNextGtoForeground() {
        if (destroying || prefs == null || windowManager == null) return false;
        if (!Settings.canDrawOverlays(this)) {
            prefs.edit()
                .putBoolean("floatingButtonActivationArmed", false)
                .putString("overlayError", "Permissão SYSTEM_ALERT_WINDOW não está ativa")
                .putLong("overlayErrorAt", System.currentTimeMillis())
                .apply();
            return false;
        }
        // A stale View token is the common reason an OEM leaves the logical service alive
        // while the visible bubble is gone. Remove all volatile overlay views and force a
        // fresh WindowManager token on the next real GTO foreground poll.
        removeAllOverlays();
        resetBubbleLandscapeGeometryStability();
        bubbleLayoutDisplayWidth = 0;
        bubbleLayoutDisplayHeight = 0;
        lastBubbleAttemptAt = 0L;
        prefs.edit()
            .putBoolean("floatingButtonActivationArmed", true)
            .putLong("floatingButtonArmedAt", System.currentTimeMillis())
            .putBoolean("overlayVisible", false)
            .remove("overlayError")
            .remove("overlayErrorAt")
            .putString("lastEvent", "Botão flutuante armado · aguardando GTO em primeiro plano")
            .apply();
        return true;
    }

    public static void markGtoLaunchRequestedIfRunning() {
        GtoObserverService current = instance;
        if (current == null || !running || current.destroying) return;
        current.mainHandler.post(current::prepareCaptureForGtoLaunch);
    }

    /**
     * Plays the dedicated automated-mode opening voice once, only after the launch
     * requested by the NVU has produced real GTO foreground evidence. Returning to GTO
     * later reuses the same launch event and is deduplicated by NvuAudioManager.
     */
    private void playGtoAutomatedStartVoiceIfEligible(long now) {
        if (prefs == null || nvuAudioManager == null) return;
        if (!prefs.getBoolean("gtoWorkLaunchPrepared", false)) return;
        long requestedAt = prefs.getLong("gtoLaunchRequestedAt", 0L);
        if (requestedAt <= 0L || now < requestedAt || now - requestedAt > 120000L) return;
        String eventId = "GTO_AUTOMATED_START|" + requestedAt;
        if (nvuAudioManager.playGtoAutomatedStartVoice(eventId)) {
            prefs.edit()
                .putString("lastGtoAutomatedStartVoiceEventId", eventId)
                .putLong("lastGtoAutomatedStartVoiceDispatchAt", now)
                .apply();
        }
    }

    /**
     * Terminal callback used by the isolated MediaProjection permission activity when
     * Android cannot even launch/deliver the consent result. This deliberately does not
     * start a new service: it clears the in-memory permission latch only when the already
     * running observer exists, while preferences retain the diagnostic for the next app
     * start. Without this path a failed permission activity could leave
     * projectionPermissionInFlight=true forever and suppress overlay recovery.
     */
    public static void reportProjectionPermissionTerminalFailure(
        Context context,
        String status,
        String error
    ) {
        if (context == null) return;
        String safeStatus = status == null || status.trim().isEmpty() ? "PERMISSION_FLOW_FAILED" : status.trim();
        String safeError = error == null ? "" : error.trim();
        clearStagedProjectionGrant(0L);
        SharedPreferences shared = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        shared.edit()
            .putBoolean("projectionPermissionInFlight", false)
            .putBoolean("projectionActive", false)
            .putBoolean("projectionSessionBound", false)
            .putBoolean("projectionSurfacePending", false)
            .putBoolean("projectionGrantValidated", false)
            .remove("projectionSessionBoundAt")
            .putString("projectionStatus", safeStatus)
            .putString("projectionError", safeError)
            .putBoolean("projectionReauthRequired", true)
            .putBoolean("projectionReauthAutoAllowed", true)
            .putBoolean("projectionReauthNoticeShown", false)
            .putString("lastEvent", safeError.isEmpty()
                ? "Falha terminal no fluxo de autorização da leitura da tela"
                : "Falha terminal no fluxo de autorização: " + safeError)
            .apply();

        GtoObserverService live = instance;
        if (live != null && running) {
            live.mainHandler.post(() -> live.handleProjectionPermissionTerminalFailure(safeStatus, safeError));
        }
    }

    private void handleProjectionPermissionTerminalFailure(String status, String error) {
        projectionPermissionInFlight = false;
        projectionSurfacePending = false;
        projectionSessionBoundAt = 0L;
        resetPendingProjectionSurfaceStability();
        suppressForegroundHideUntil = System.currentTimeMillis() + PERMISSION_RETURN_GRACE_MS;
        projectionStatus = status == null || status.isEmpty() ? "PERMISSION_FLOW_FAILED" : status;
        prefs.edit()
            .putBoolean("projectionPermissionInFlight", false)
            .putBoolean("projectionActive", projectionActive)
            .putBoolean("projectionSessionBound", false)
            .putBoolean("projectionSurfacePending", false)
            .putBoolean("projectionGrantValidated", false)
            .remove("projectionSessionBoundAt")
            .putString("projectionStatus", projectionStatus)
            .putString("projectionError", error == null ? "" : error)
            .putBoolean("projectionReauthRequired", true)
            .putBoolean("projectionReauthAutoAllowed", true)
            .putBoolean("projectionReauthNoticeShown", false)
            .apply();
        updateFreightTouchPulseSensor();
        try {
            startForegroundForTypes(projectionActive);
        } catch (Exception ex) {
            prefs.edit()
                .putString("startError", describeError(ex))
                .putString("lastEvent", "Falha ao restaurar o serviço após erro de autorização")
                .apply();
        }
        updateNotification();
        scheduleBubbleRestoreAfterPermission();
        if (captureIsNeededForCurrentState()) {
            showStatusChip("A autorização não concluiu. O NVU vai tentar reabrir a confirmação automaticamente.", 3800L);
            mainHandler.postDelayed(
                () -> ensureProjectionAuthorizationIfNeeded(System.currentTimeMillis()),
                320L
            );
        }
    }

    public static void reportMainActivityForeground(boolean foreground) {
        GtoObserverService live = instance;
        if (live == null || !running) return;
        live.mainHandler.post(() -> {
            live.nvuMainActivityForeground = foreground;
            if (live.prefs != null) {
                live.prefs.edit()
                    .putBoolean("nvuMainActivityForeground", foreground)
                    .putLong("nvuMainActivityForegroundChangedAt", System.currentTimeMillis())
                    .apply();
            }
        });
    }

    public static void stageProjectionGrantFromPermissionHost(int resultCode, Intent resultData, long resultAt) {
        if (resultCode != android.app.Activity.RESULT_OK || resultData == null || resultAt <= 0L) return;
        synchronized (PROJECTION_GRANT_LOCK) {
            stagedProjectionGrantResultCode = resultCode;
            stagedProjectionGrantData = resultData;
            stagedProjectionGrantResultAt = resultAt;
        }
    }

    public static boolean rescueStagedProjectionGrantIfRunning(long expectedResultAt) {
        GtoObserverService live = instance;
        if (live == null || !running) return false;
        live.mainHandler.post(() -> live.bindStagedProjectionGrantIfNeeded(expectedResultAt));
        return true;
    }

    private static Intent peekStagedProjectionGrant(int expectedCode, long minResultAt) {
        synchronized (PROJECTION_GRANT_LOCK) {
            if (stagedProjectionGrantData == null
                || stagedProjectionGrantResultCode != expectedCode
                || stagedProjectionGrantResultAt < minResultAt) return null;
            return stagedProjectionGrantData;
        }
    }

    private static void clearStagedProjectionGrant(long throughResultAt) {
        synchronized (PROJECTION_GRANT_LOCK) {
            if (stagedProjectionGrantData == null) return;
            if (throughResultAt > 0L && stagedProjectionGrantResultAt > throughResultAt) return;
            stagedProjectionGrantData = null;
            stagedProjectionGrantResultCode = 0;
            stagedProjectionGrantResultAt = 0L;
        }
    }

    private void bindStagedProjectionGrantIfNeeded(long expectedResultAt) {
        if (destroying || !running) return;
        if (projectionActive || projectionSurfacePending || mediaProjection != null) {
            clearStagedProjectionGrant(expectedResultAt);
            projectionPermissionInFlight = false;
            prefs.edit().putBoolean("projectionPermissionInFlight", false).apply();
            return;
        }
        Intent staged = peekStagedProjectionGrant(android.app.Activity.RESULT_OK, expectedResultAt);
        if (staged == null) return;
        try {
            startForegroundForTypes(true);
            prefs.edit()
                .putLong("projectionGrantDirectRescueAt", System.currentTimeMillis())
                .putString("lastEvent", "Compartilhamento aceito · resgatando autorização diretamente no observador")
                .apply();
            acceptProjectionGrantOnMainThread(android.app.Activity.RESULT_OK, staged);
        } catch (Exception ex) {
            prefs.edit()
                .putString("projectionError", "Grant rescue: " + describeError(ex))
                .putLong("projectionErrorAt", System.currentTimeMillis())
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", true)
                .putString("lastEvent", "Falha no resgate direto da autorização; recuperação automática continuará")
                .apply();
        }
    }

    public static boolean requestProjectionPermissionIfRunning() {
        GtoObserverService live = instance;
        if (live == null || !running) return false;
        live.mainHandler.post(live::requestProjectionPermission);
        return true;
    }

    /**
     * Consumes the MediaProjection grant immediately while the transparent consent host
     * is still alive. The observer service is already running whenever this activity can
     * be launched, so keeping the grant in-process removes the asynchronous service-intent
     * race that could briefly make an accepted grant look unauthorized again.
     */
    // HF30 keeps ACTION_START_PROJECTION as the process-recreation-safe authoritative
    // path and also stages RESULT_OK in-process so an OEM-delayed service Intent cannot
    // strand an already accepted one-use grant.

    private boolean acceptProjectionGrantOnMainThread(int resultCode, Intent resultData) {
        if (resultCode != android.app.Activity.RESULT_OK || resultData == null) return false;
        if (projectionActive || (projectionSurfacePending && mediaProjection != null)) {
            clearStagedProjectionGrant(prefs.getLong("projectionConsentResultAt", 0L));
            projectionPermissionInFlight = false;
            prefs.edit()
                .putBoolean("projectionPermissionInFlight", false)
                .putBoolean("projectionGrantValidated", true)
                .putLong("projectionGrantValidatedAt", System.currentTimeMillis())
                .apply();
            return true;
        }
        projectionPermissionAfterGtoOpenPending = false;
        projectionPermissionAfterGtoOpenArmedAt = 0L;
        projectionPermissionInFlight = true;
        suppressForegroundHideUntil = System.currentTimeMillis() + PERMISSION_RETURN_GRACE_MS;
        prefs.edit()
            .putBoolean("projectionPermissionInFlight", true)
            .remove("projectionPermissionAfterGtoOpenPending")
            .remove("projectionPermissionAfterGtoOpenArmedAt")
            .putLong("projectionGrantReceivedAt", System.currentTimeMillis())
            .putInt("projectionGrantResultCode", resultCode)
            .putString("projectionStatus", "CONSENT_GRANTED_BINDING")
            .putString("lastEvent", "Compartilhamento aceito · validando token no observador")
            .apply();
        return startProjection(resultCode, resultData);
    }

    public static boolean markProjectionPermissionInFlightIfRunning() {
        GtoObserverService live = instance;
        if (live == null || !running) return false;
        live.mainHandler.post(() -> {
            live.projectionPermissionInFlight = true;
            live.suppressForegroundHideUntil = System.currentTimeMillis() + PERMISSION_RETURN_GRACE_MS;
            live.projectionStatus = "REQUESTING_PERMISSION_APP";
            live.prefs.edit()
                .putBoolean("projectionPermissionInFlight", true)
                .putString("projectionStatus", live.projectionStatus)
                .apply();
        });
        return true;
    }

    public static boolean recoverIfEnabled(Context context) {
        if (context == null || running) return running;
        Context appContext = context.getApplicationContext();
        SharedPreferences preferences = appContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE);
        if (!preferences.getBoolean("enabled", false)) return false;
        if (!Settings.canDrawOverlays(appContext)) {
            preferences.edit().putString("startError", "Permissão de sobreposição não está ativa.").apply();
            return false;
        }
        if (!hasUsageStatsAccess(appContext)) {
            preferences.edit().putString("startError", "Acesso de uso necessário para detectar o GTO não está ativo.").apply();
            return false;
        }
        try {
            preferences.edit().remove("startError").apply();
            Intent intent = new Intent(appContext, GtoObserverService.class).setAction(ACTION_START);
            ContextCompat.startForegroundService(appContext, intent);
            return true;
        } catch (Exception ex) {
            preferences.edit().putString("startError", describeError(ex)).apply();
            return false;
        }
    }

    public static String describeError(Throwable error) {
        if (error == null) return "Erro desconhecido";
        String message = error.getMessage();
        String value = error.getClass().getSimpleName() + (message == null || message.trim().isEmpty() ? "" : ": " + message.trim());
        return value.length() > 220 ? value.substring(0, 220) : value;
    }

    private void recordNeutralScreenObservation(String kind, String normalizedText) {
        if (prefs == null) return;
        prefs.edit()
            .putString("lastNeutralScreenKind", kind == null ? "OTHER" : kind)
            .putString("lastNeutralScreenText", truncate(normalizedText == null ? "" : normalizedText, 240))
            .putLong("lastNeutralScreenAt", System.currentTimeMillis())
            .apply();
    }

    private void reportFrameProcessingError(String area, Throwable error) {
        String detail = describeError(error);
        long now = System.currentTimeMillis();
        prefs.edit()
            .putString("frameProcessingErrorArea", area == null ? "captura" : area)
            .putString("frameProcessingError", detail)
            .putLong("frameProcessingErrorAt", now)
            .putString("lastEvent", "Falha em " + (area == null ? "captura" : area) + ": " + detail)
            .apply();
        recordObserverIncident("FRAME_PROCESSING", (area == null ? "captura" : area) + " · " + detail);
        if (gtoForeground && !screenAnalysisPausedOutsideGto
            && now - lastDriverErrorNoticeAt >= DRIVER_ERROR_NOTICE_THROTTLE_MS) {
            lastDriverErrorNoticeAt = now;
            showStatusChip("Falha na leitura: " + detail, 4200L);
        }
    }

    private static boolean hasUsageStatsAccess(Context context) {
        AppOpsManager appOps = (AppOpsManager) context.getSystemService(Context.APP_OPS_SERVICE);
        if (appOps == null) return false;
        int mode;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            mode = appOps.unsafeCheckOpNoThrow(
                AppOpsManager.OPSTR_GET_USAGE_STATS,
                android.os.Process.myUid(),
                context.getPackageName()
            );
        } else {
            mode = appOps.checkOpNoThrow(
                AppOpsManager.OPSTR_GET_USAGE_STATS,
                android.os.Process.myUid(),
                context.getPackageName()
            );
        }
        return mode == AppOpsManager.MODE_ALLOWED;
    }

    public static void reportPreciseTouch(float x, float y, long eventTime) {
        GtoObserverService service = instance;
        if (service == null || !running) return;
        service.mainHandler.post(() -> service.handlePreciseTouch(x, y, eventTime));
    }

    private static final class CaptureRuntimeSnapshot {
        final long generation;
        final long lastFrameAt;
        final long lastAnalyzedAt;
        final boolean projectionActive;
        final boolean tokenPresent;
        final boolean displayPresent;
        final boolean readerPresent;
        final boolean handlerPresent;
        final int width;
        final int height;
        final String readerIdentity;
        final String recoveryState;
        final long recoveryStartedAt;

        CaptureRuntimeSnapshot(
            long generation,
            long lastFrameAt,
            long lastAnalyzedAt,
            boolean projectionActive,
            boolean tokenPresent,
            boolean displayPresent,
            boolean readerPresent,
            boolean handlerPresent,
            int width,
            int height,
            String readerIdentity,
            String recoveryState,
            long recoveryStartedAt
        ) {
            this.generation = generation;
            this.lastFrameAt = lastFrameAt;
            this.lastAnalyzedAt = lastAnalyzedAt;
            this.projectionActive = projectionActive;
            this.tokenPresent = tokenPresent;
            this.displayPresent = displayPresent;
            this.readerPresent = readerPresent;
            this.handlerPresent = handlerPresent;
            this.width = width;
            this.height = height;
            this.readerIdentity = readerIdentity == null ? "" : readerIdentity;
            this.recoveryState = recoveryState == null ? RECOVERY_IDLE : recoveryState;
            this.recoveryStartedAt = recoveryStartedAt;
        }

        static CaptureRuntimeSnapshot initial() {
            return new CaptureRuntimeSnapshot(
                0L, 0L, 0L, false, false, false, false, false,
                0, 0, "", RECOVERY_IDLE, 0L
            );
        }
    }

    @Override
    public void onCreate() {
        super.onCreate();
        running = true;
        instance = this;
        prefs = getSharedPreferences(PREFS_NAME, MODE_PRIVATE);
        // HF54: repeat upgrade recovery when the native observer starts. This covers the
        // common login flow where FirebaseAuth was not restored yet during MainActivity
        // onStart; recovery remains idempotent and never deletes a sealed queue entry.
        GtoAutoTripSync.recoverLegacyPendingStateOnAuthenticatedStart(this, prefs);
        projectionPermissionAfterGtoOpenPending = prefs.getBoolean("projectionPermissionAfterGtoOpenPending", false);
        projectionPermissionAfterGtoOpenArmedAt = prefs.getLong("projectionPermissionAfterGtoOpenArmedAt", 0L);
        // The bridge is durable for the authorized GTO session. Restoring this latch is
        // necessary after service recreation; otherwise UsageStats lag can block the
        // two-frame freight-list return probe even though the current capture is valid.
        projectionVerifiedGtoBridgeActive = prefs.getBoolean("projectionVerifiedGtoBridgeActive", false);
        // MainActivity foreground is process/instance-local. Never restore a stale true
        // value from SharedPreferences after service recreation; onResume() is the only
        // authority allowed to assert that NVU itself is currently in front.
        nvuMainActivityForeground = false;
        long serviceNow = System.currentTimeMillis();
        prefs.edit()
            .putBoolean("projectionActive", false)
            .putBoolean("projectionPermissionInFlight", false)
            .putBoolean("projectionSessionBound", false)
            .putBoolean("projectionSurfacePending", false)
            .putBoolean("projectionGrantValidated", false)
            .remove("projectionSessionBoundAt")
            .remove("projectionConsentResultAt")
            .remove("projectionGrantReceivedAt")
            .putBoolean("overlayVisible", false)
            .putBoolean("observerOperationalReady", false)
            .putString("observerOperationalStatus", "STARTING")
            .putLong("serviceStartedAt", serviceNow)
            .putLong("serviceHeartbeatAt", serviceNow)
            .remove("startError")
            .apply();
        updateObserverLifecycleStatus(serviceNow);
        windowManager = (WindowManager) getSystemService(WINDOW_SERVICE);
        usageStatsManager = (UsageStatsManager) getSystemService(USAGE_STATS_SERVICE);
        notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);
        textRecognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);
        selectionTextRecognizer = TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);
        nvuAudioManager = new NvuAudioManager(this, detail ->
            recordObserverIncident("AUTOMATION_VOICE_AUDIO", detail));
        recordObserverEvent("SERVICE_STARTED", "Observador inicializado");
        sanitizeLegacyUntrustedPendingSelectionOnStartup();

        // HF42 crash-safe terminal proof recovery. A certified result is stronger than
        // volatile service/UI state. If the dedicated proof store write was interrupted
        // but the synchronous runtime/session snapshot survived, promote that evidence
        // back into the separate escrow before any stale-state cleanup can run.
        String runtimeCertifiedSession = prefs.getString("resultCertifiedSessionId", "");
        if (runtimeCertifiedSession.isEmpty()) runtimeCertifiedSession = prefs.getString("gtoTripSessionId", "");
        if (prefs.getBoolean("resultCertifiedLatched", false)
            && (isTerminalCompletionCommittedForCurrentSession()
                || !prefs.getBoolean("resultWatchedAdEvidence", false))
            && !runtimeCertifiedSession.isEmpty()
            && GtoAutoTripSync.hasRecoverableSessionSnapshot(this, runtimeCertifiedSession, true)
            && !GtoResultProofStore.hasCertified(this, runtimeCertifiedSession)) {
            GtoResultProofStore.certify(
                this, runtimeCertifiedSession, prefs.getString("resultValue", ""),
                prefs.getString("resultSnapshotPath", ""), prefs.getLong("resultCertifiedAt", serviceNow)
            );
        }
        // If a previous lifecycle path lost volatile runtime keys before the completed
        // payload was sealed, restore the immutable freight snapshot and result proof
        // first, then resume RESULT_DETECTED instead of silently IDLE.
        String protectedResultSession = GtoResultProofStore.protectedSessionId(this);
        String runtimeSessionBeforeProofRecovery = prefs.getString("gtoTripSessionId", "").trim();
        String runtimeStateBeforeProofRecovery = prefs.getString("tripState", STATE_IDLE);
        boolean differentActiveRuntimeSession = !runtimeSessionBeforeProofRecovery.isEmpty()
            && !runtimeSessionBeforeProofRecovery.equals(protectedResultSession)
            && isRecoverableActiveState(runtimeStateBeforeProofRecovery);
        if (!protectedResultSession.isEmpty()
            && !differentActiveRuntimeSession
            && GtoAutoTripSync.hasRecoverableSessionSnapshot(this, protectedResultSession, true)
            && !GtoAutoTripSync.hasPendingSession(this, protectedResultSession)) {
            prefs.edit()
                .putString("gtoTripSessionId", protectedResultSession)
                .putLong("gtoTripSessionStartedAt", Math.max(1L, prefs.getLong("gtoTripSessionStartedAt", serviceNow)))
                .putString("tripState", STATE_RESULT_DETECTED)
                .putString("completionStatus", "RESULT_CERTIFIED_AUTO_PENDING")
                .putString("gtoTripSyncStatus", GtoAutoTripSync.STATUS_IN_PROGRESS)
                .putString("lastEvent", "Entrega certificada restaurada do cofre local · retomando registro automático")
                .apply();
            GtoAutoTripSync.restoreLockedFreightToPrefs(this, prefs, protectedResultSession);
            GtoResultProofStore.restoreToRuntime(this, prefs, protectedResultSession);
        }
        // MediaProjection itself cannot survive process death, but the immutable FIX18
        // operation/freight snapshot can. Preserve a real in-progress session and only
        // require the driver to re-authorize screen reading when capture is needed again.
        String restoredState = prefs.getString("tripState", STATE_IDLE);
        String restoredCompletion = prefs.getString("completionStatus", "");
        String restoredSyncStatus = prefs.getString("gtoTripSyncStatus", "");
        boolean recoverCompletedTrip = STATE_RESULT_CONFIRMED.equals(restoredState)
            && "CONFIRMED_NORMAL".equals(restoredCompletion)
            && !GtoAutoTripSync.STATUS_SYNCED.equals(restoredSyncStatus);
        boolean recoverActiveTrip = isRecoverableActiveState(restoredState)
            && hasFreshDurableSession(restoredState);
        boolean recoverWaitingObserver = STATE_WAITING_FREIGHT.equals(restoredState)
            && prefs.getBoolean("enabled", false);
        String restoredResultAction = prefs.getString("resultAction", "");
        boolean restoredTerminalCommit = prefs.getBoolean("resultTerminalCommitLatched", false)
            && prefs.getString("gtoTripSessionId", "").trim().equals(
                prefs.getString("resultTerminalCommitSessionId", prefs.getString("gtoTripSessionId", "")).trim()
            );
        boolean recoverExactReceive = recoverActiveTrip
            && (STATE_RESULT_DETECTED.equals(restoredState) || STATE_AWAITING_BONUS.equals(restoredState))
            && restoredResultAction != null
            && restoredResultAction.startsWith("RECEIVE")
            && prefs.getBoolean("resultReceiveLatched", false)
            && prefs.getBoolean("resultCertifiedLatched", false)
            && (restoredTerminalCommit || !prefs.getBoolean("resultWatchedAdEvidence", false));
        boolean recoverCertifiedResult = recoverActiveTrip
            && (STATE_RESULT_DETECTED.equals(restoredState) || STATE_AWAITING_BONUS.equals(restoredState))
            && prefs.getBoolean("resultCertifiedLatched", false)
            && (restoredTerminalCommit || !prefs.getBoolean("resultWatchedAdEvidence", false));

        if (recoverCompletedTrip) {
            prefs.edit()
                .putString("gtoTripSyncStatus", GtoAutoTripSync.STATUS_PENDING)
                .remove("gtoTripSyncError")
                .putString("lastEvent", "Entrega concluída preservada · retomando sincronização NVU")
                .apply();
        } else if (recoverActiveTrip) {
            // Short-lived frame references do not survive process death. However, when
            // selection identity was already CONFIRMED and only a specific field is under
            // REVIEW_REQUIRED, that durable review is restored exactly. An unconfirmed
            // candidate safely falls back to WAITING_FREIGHT. Locked trips remain untouched.
            String recoverableState = GtoSessionRecoveryPolicy.restoredState(
                restoredState,
                prefs.getString("selectionIdentityStatus", ""),
                prefs.getString("selectionConfirmationStatus", ""),
                prefs.getString("reviewRequiredField", ""),
                prefs.getString("selectionIdentitySource", "")
            );
            prefs.edit()
                .putString("tripState", recoverableState)
                .putString("projectionStatus", "REAUTH_REQUIRED_AFTER_RESTART")
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", true)
                .putBoolean("projectionReauthNoticeShown", false)
                .putString("lastEvent", STATE_TRIP_IN_PROGRESS.equals(recoverableState)
                    ? "Viagem GTO preservada após reinício · autorize a leitura da tela para finalizar"
                    : "Sessão GTO preservada após reinício · autorize a leitura da tela")
                .apply();
        } else if (recoverWaitingObserver) {
            // WAITING_FREIGHT has no immutable selected-row snapshot yet, but the observer
            // operation itself is durable. If Android recreates the sticky service, keep
            // waiting for a freight and automatically request a fresh MediaProjection; do
            // not silently fall back to IDLE and leave GTO Observe dead.
            prefs.edit()
                .putString("tripState", STATE_WAITING_FREIGHT)
                .putString("projectionStatus", "REAUTH_REQUIRED_AFTER_SERVICE_RESTART")
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", true)
                .putBoolean("projectionReauthNoticeShown", false)
                .putString("lastEvent", "Observador restaurado após reinício · aguardando GTO para renovar a leitura")
                .apply();
        } else if (!STATE_IDLE.equals(restoredState)) {
            String staleSessionId = prefs.getString("gtoTripSessionId", "");
            if (clearTripAnalysis()) {
                GtoAutoTripSync.discardSessionSnapshot(this, staleSessionId);
            }
            prefs.edit()
                .putString("tripState", STATE_IDLE)
                .putString("lastEvent", "Sessão GTO anterior encerrada com segurança")
                .apply();
        }
        createNotificationChannel();
        if (recoverCompletedTrip) {
            mainHandler.postDelayed(() -> {
                String recoveredSession = prefs.getString("gtoTripSessionId", "").trim();
                boolean queued = GtoTripSubmissionCoordinator.submitCompletedTrip(this, prefs, automaticTripSyncListener());
                if (queued) {
                    markResultProofSealedPendingServerAck(recoveredSession);
                } else {
                    armCompletionQueueSealRecovery(recoveredSession, System.currentTimeMillis());
                }
            }, 900L);
        } else if (recoverExactReceive) {
            // The exact Receber action is durable. A process restart after the tap must
            // continue completion immediately instead of waiting for the GTO screen again.
            mainHandler.postDelayed(this::confirmNormalResultAutomatically, 250L);
        } else if (recoverCertifiedResult) {
            // HF47: restore the volatile continuity clock from durable certification.
            // HF46 restored the proof/state but left resultScreenLastSeenAt at zero, so
            // its certified-dialog disappearance gate never ran after a service/process
            // recreation. A later freight-list boundary was then the only thing capable
            // of sealing the otherwise-completed delivery.
            resultScreenLastSeenAt = GtoCertifiedResultLifecyclePolicy.restoreCertifiedSeenAt(
                true, resultScreenLastSeenAt, prefs.getLong("resultCertifiedAt", 0L), serviceNow
            );
            resultExitSeenAt = 0L;
            resultDialogVisualAbsentFrames = 0;
            resultAdUiLastSeenAt = prefs.getLong("resultAdUiLastSeenAt", 0L);
            detectedResultValue = prefs.getInt("resultValueConsensusVersion", 0) == GtoResultValueConsensus.SCHEMA_VERSION
                ? GtoResultValueConsensus.canonical(prefs.getString("resultValueConsensusStable", ""))
                : "";
            if (detectedResultValue.isEmpty()) {
                detectedResultValue = GtoResultValueConsensus.canonical(prefs.getString("resultValue", ""));
            }
            resultExitResolverGeneration++;
            prefs.edit()
                .putString("resultTerminalResolverStatus", "RECOVERED_CERTIFIED_RESULT")
                .putString("lastEvent", "Entrega certificada recuperada · retomando registro automático protegido")
                .apply();
            armCertifiedResultTerminalFailsafe(
                prefs.getString("gtoTripSessionId", protectedResultSession),
                prefs.getLong("resultCertifiedAt", serviceNow)
            );
            mainHandler.postDelayed(this::flushAutomaticTripQueue, 1200L);
        } else {
            mainHandler.postDelayed(this::flushAutomaticTripQueue, 1200L);
        }
        mainHandler.postDelayed(this::reconcileAcknowledgedTripForNextFreight, 1450L);
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        String action = intent != null ? intent.getAction() : ACTION_START;

        if (ACTION_STOP.equals(action)) {
            clearStagedProjectionGrant(0L);
            prefs.edit()
                .putBoolean("enabled", false)
                .putBoolean("overlayVisible", false)
                .putBoolean("observerOperationalReady", false)
                .putString("observerOperationalStatus", "OFF")
                .putBoolean("observerLifecycleActive", false)
                .putString("observerLifecycleStatus", GtoObserverLifecyclePolicy.SERVICE_STOPPED)
                .putLong("observerLifecycleChangedAt", System.currentTimeMillis())
                .remove("startError")
                .apply();
            stopProjection();
            removeAllOverlays();
            stopForeground(STOP_FOREGROUND_REMOVE);
            stopSelf();
            return START_NOT_STICKY;
        }

        if (ACTION_PROJECTION_DENIED.equals(action)) {
            clearStagedProjectionGrant(0L);
            projectionPermissionAfterGtoOpenPending = false;
            projectionPermissionAfterGtoOpenArmedAt = 0L;
            projectionPermissionInFlight = false;
            suppressForegroundHideUntil = System.currentTimeMillis() + PERMISSION_RETURN_GRACE_MS;
            projectionActive = false;
            projectionSurfacePending = false;
            projectionSessionBoundAt = 0L;
            resetPendingProjectionSurfaceStability();
            projectionStatus = "DENIED";
            prefs.edit()
                .putBoolean("projectionActive", false)
                .putBoolean("projectionSessionBound", false)
                .putBoolean("projectionSurfacePending", false)
                .putBoolean("projectionGrantValidated", false)
                .putString("projectionStatus", projectionStatus)
                .putBoolean("projectionPermissionInFlight", false)
                .remove("projectionPermissionAfterGtoOpenPending")
                .remove("projectionPermissionAfterGtoOpenArmedAt")
                .putString("screenState", "CAPTURE_DENIED")
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", false)
                .putBoolean("projectionReauthNoticeShown", false)
                .putBoolean("touchCaptureNeeded", false)
                .putString("lastEvent", "Captura de tela não autorizada")
                .apply();
            if (STATE_WAITING_FREIGHT.equals(getTripState())) {
                showToast("A leitura da tela é necessária. Abra a bolinha NVU e toque em Autorizar leitura da tela.");
            }
            updateFreightTouchPulseSensor();
            try {
                startForegroundForTypes(false);
            } catch (Exception ex) {
                prefs.edit()
                    .putString("startError", describeError(ex))
                    .putString("lastEvent", "Falha ao manter serviço após recusa da captura")
                    .apply();
            }
            updateNotification();
            scheduleBubbleRestoreAfterPermission();
            return START_STICKY;
        }

        long startedAt = System.currentTimeMillis();
        prefs.edit()
            .putBoolean("enabled", true)
            .putLong("serviceHeartbeatAt", startedAt)
            .remove("startError")
            .apply();
        boolean projectionGrantAction = ACTION_START_PROJECTION.equals(action);
        try {
            // The RESULT_OK handoff is the exact point where Android allows the
            // mediaProjection foreground-service type on Android 14+. Promote the
            // already-running observer *before* getMediaProjection(), and never
            // downgrade while a projection is bound/active.
            startForegroundForTypes(
                projectionGrantAction || projectionActive || projectionSurfacePending || mediaProjection != null
            );
        } catch (Exception ex) {
            // A transient failure while adding the mediaProjection service type must not
            // kill GTO Observe. Keep the base observer foreground if possible, preserve
            // all trip state, and let the supervisor retry the Android consent path.
            String detail = describeError(ex);
            prefs.edit()
                .putString("startError", detail)
                .putString("projectionError", projectionGrantAction ? "FGS projection type: " + detail : detail)
                .putLong("serviceHeartbeatAt", startedAt)
                .putString("lastEvent", projectionGrantAction
                    ? "Falha transitória ao promover serviço de captura · observador preservado"
                    : "Falha ao atualizar serviço em primeiro plano · observador continuará tentando")
                .apply();
            try {
                startForegroundForTypes(false);
            } catch (Exception fallbackEx) {
                prefs.edit()
                    .putString("startError", describeError(fallbackEx))
                    .putString("lastEvent", "Android recusou a atualização do foreground; serviço sticky preservado")
                    .apply();
            }
            if (projectionGrantAction) {
                projectionPermissionInFlight = false;
                projectionStatus = "PROJECTION_FGS_PROMOTION_FAILED";
                prefs.edit()
                    .putBoolean("projectionPermissionInFlight", false)
                    .putString("projectionStatus", projectionStatus)
                    .putBoolean("projectionReauthRequired", true)
                    .putBoolean("projectionReauthAutoAllowed", true)
                    .putBoolean("projectionReauthNoticeShown", false)
                    .apply();
            }
        }
        scheduleForegroundPoll();

        if (ACTION_START_PROJECTION.equals(action)) {
            int resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, 0);
            Intent resultData = readProjectionData(intent);
            if (resultData == null && resultCode == android.app.Activity.RESULT_OK) {
                resultData = peekStagedProjectionGrant(
                    resultCode, prefs.getLong("projectionConsentResultAt", 0L)
                );
            }
            boolean accepted = resultCode == android.app.Activity.RESULT_OK
                && resultData != null
                && acceptProjectionGrantOnMainThread(resultCode, resultData);
            if (!accepted) {
                projectionPermissionInFlight = false;
                projectionActive = false;
                projectionSurfacePending = false;
                projectionSessionBoundAt = 0L;
                projectionStatus = "GRANT_DATA_INVALID";
                prefs.edit()
                    .putBoolean("projectionPermissionInFlight", false)
                    .putBoolean("projectionActive", false)
                    .putBoolean("projectionSessionBound", false)
                    .putBoolean("projectionSurfacePending", false)
                    .putBoolean("projectionGrantValidated", false)
                    .putString("projectionStatus", projectionStatus)
                    .putString("projectionError", "O Android retornou autorização sem um token de captura válido.")
                    .putBoolean("projectionReauthRequired", true)
                    .putBoolean("projectionReauthAutoAllowed", true)
                    .putBoolean("projectionReauthNoticeShown", false)
                    .putString("lastEvent", "Autorização recebida sem token de captura válido")
                    .apply();
                mainHandler.postDelayed(
                    () -> ensureProjectionAuthorizationIfNeeded(System.currentTimeMillis()),
                    320L
                );
            }
            scheduleBubbleRestoreAfterPermission();
        }

        return START_STICKY;
    }

    @SuppressWarnings("deprecation")
    private Intent readProjectionData(Intent intent) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            return intent.getParcelableExtra(EXTRA_RESULT_DATA, Intent.class);
        }
        return intent.getParcelableExtra(EXTRA_RESULT_DATA);
    }

    private void scheduleForegroundPoll() {
        mainHandler.removeCallbacks(foregroundPoll);
        lastUsageQueryAt = Math.max(0L, System.currentTimeMillis() - 60_000L);
        mainHandler.post(foregroundPoll);
    }

    private void refreshForegroundPackage() {
        if (usageStatsManager == null || !hasUsageStatsAccess()) return;

        long now = System.currentTimeMillis();
        long from = Math.max(0L, lastUsageQueryAt - 1200L);
        lastUsageQueryAt = now;

        UsageEvents events = usageStatsManager.queryEvents(from, now);
        UsageEvents.Event event = new UsageEvents.Event();
        long newestForeground = 0L;
        String latestPackage = null;
        boolean sawTransientForeground = false;

        while (events.hasNextEvent()) {
            events.getNextEvent(event);
            int type = event.getEventType();
            long at = event.getTimeStamp();
            String packageName = event.getPackageName();
            String className = event.getClassName();

            boolean enteredForeground = type == UsageEvents.Event.MOVE_TO_FOREGROUND;
            boolean enteredBackground = type == UsageEvents.Event.MOVE_TO_BACKGROUND;
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                enteredForeground = enteredForeground || type == UsageEvents.Event.ACTIVITY_RESUMED;
                enteredBackground = enteredBackground
                    || type == UsageEvents.Event.ACTIVITY_PAUSED
                    || type == UsageEvents.Event.ACTIVITY_STOPPED;
            }

            boolean transientSurface = isTransientForegroundEvent(packageName, className);
            if (transientSurface) {
                if (enteredForeground && at >= transientForegroundSurfaceAt) {
                    transientForegroundSurfaceActive = true;
                    transientForegroundSurfaceAt = at;
                    transientForegroundPackage = packageName == null ? "SYSTEM_UI" : packageName;
                    sawTransientForeground = true;
                }
                if (enteredBackground
                    && transientForegroundSurfaceActive
                    && at >= transientForegroundSurfaceAt
                    && (packageName == null || packageName.equals(transientForegroundPackage))) {
                    transientForegroundSurfaceActive = false;
                    transientForegroundSurfaceAt = at;
                    transientForegroundPackage = "";
                }
            }

            if (GTO_PACKAGE.equals(packageName)) {
                if (enteredForeground) {
                    lastGtoForegroundEventAt = Math.max(lastGtoForegroundEventAt, at);
                    transientForegroundSurfaceActive = false;
                    transientForegroundPackage = "";
                }
                if (enteredBackground) lastGtoBackgroundEventAt = Math.max(lastGtoBackgroundEventAt, at);
            }

            if (enteredForeground && at >= newestForeground) {
                if (transientSurface) continue;
                newestForeground = at;
                latestPackage = packageName;
                transientForegroundSurfaceActive = false;
                transientForegroundPackage = "";
            }
        }

        boolean visualGtoProofFresh = lastVisualGtoForegroundEvidenceAt > 0L
            && now >= lastVisualGtoForegroundEvidenceAt
            && now - lastVisualGtoForegroundEvidenceAt <= VISUAL_GTO_EVIDENCE_FRESH_MS;
        boolean permissionReturnGrace = now < suppressForegroundHideUntil;
        if (latestPackage != null) {
            // HF63 root fix: UsageStats is an event stream, not a real-time screen oracle.
            // Some OEMs keep replaying the last call/browser foreground event after the
            // driver has already returned to GTO. A strict GTO freight/result frame sampled
            // later than that event is stronger CURRENT evidence. Let it win until Android
            // emits a genuinely newer application event. This prevents a 350 ms oscillation
            // where visual recovery sets GTO and the next overlapping UsageStats query pauses
            // the detector again. MainActivity and transient-system vetoes remain intact.
            boolean visualProofOutranksUsageEvent = visualGtoProofFresh
                && lastVisualGtoForegroundEvidenceAt >= newestForeground
                && !nvuMainActivityForeground
                && !transientForegroundSurfaceActive;
            boolean ownPermissionReturn = getPackageName().equals(latestPackage) && permissionReturnGrace;
            foregroundPackage = visualProofOutranksUsageEvent || (ownPermissionReturn
                    && visualGtoProofFresh
                    && lastVisualGtoForegroundEvidenceAt >= newestForeground)
                ? GTO_PACKAGE
                : latestPackage;
        } else if (!sawTransientForeground
            && GTO_PACKAGE.equals(foregroundPackage)
            && lastGtoBackgroundEventAt > lastGtoForegroundEventAt
            && !visualGtoProofFresh) {
            foregroundPackage = "";
        }

        persistForegroundRuntimeIfDue(now);
    }

    private void persistServiceHeartbeatIfDue(long now) {
        if (now - lastHeartbeatPersistAt < HEARTBEAT_PERSIST_INTERVAL_MS) return;
        lastHeartbeatPersistAt = now;
        prefs.edit().putLong("serviceHeartbeatAt", now).apply();
    }

    private void persistForegroundRuntimeIfDue(long now) {
        String currentPackage = foregroundPackage == null ? "" : foregroundPackage;
        boolean changed = !currentPackage.equals(lastPersistedForegroundPackage)
            || lastGtoForegroundEventAt != lastPersistedGtoForegroundEventAt
            || lastGtoBackgroundEventAt != lastPersistedGtoBackgroundEventAt;
        if (!changed && now - lastForegroundStatusPersistAt < FOREGROUND_STATUS_PERSIST_INTERVAL_MS) return;
        lastForegroundStatusPersistAt = now;
        lastPersistedForegroundPackage = currentPackage;
        lastPersistedGtoForegroundEventAt = lastGtoForegroundEventAt;
        lastPersistedGtoBackgroundEventAt = lastGtoBackgroundEventAt;
        prefs.edit()
            .putString("foregroundPackage", currentPackage)
            .putLong("lastGtoForegroundEventAt", lastGtoForegroundEventAt)
            .putLong("lastGtoBackgroundEventAt", lastGtoBackgroundEventAt)
            .apply();
    }

    private void persistFreightRuntimeStatus(String state, int freightCount, long now, long sequence) {
        String safeState = state == null ? "UNKNOWN" : state;
        int safeCount = Math.max(0, freightCount);
        String previousState = lastPersistedFreightRuntimeState;
        int previousCount = lastPersistedFreightCount;
        boolean changed = !safeState.equals(previousState)
            || safeCount != previousCount;
        if (!changed && now - lastFreightRuntimePersistAt < FREIGHT_RUNTIME_PERSIST_INTERVAL_MS) return;
        lastFreightRuntimePersistAt = now;
        lastPersistedFreightRuntimeState = safeState;
        lastPersistedFreightCount = safeCount;
        SharedPreferences.Editor editor = prefs.edit()
            .putString("screenState", safeState)
            .putInt("freightCount", safeCount);
        if ("FREIGHT_LIST".equals(safeState)) {
            editor.putLong("freightStructureAt", now)
                .putLong("freightFrameSequence", sequence);
        }
        editor.apply();

        if (changed) {
            mainHandler.post(this::refreshMenuContents);
            // HF16: raw button geometry updates the internal screen state immediately,
            // but the driver-facing "lista detectada" message is emitted only after OCR
            // confirms at least one same-row monetary freight value.
        }
    }

    private boolean validateObserverRuntimePermissions() {
        boolean overlayOk = Settings.canDrawOverlays(this);
        boolean usageOk = hasUsageStatsAccess();
        if (overlayOk && usageOk) {
            if (!lastRuntimePermissionError.isEmpty() || (prefs != null && !prefs.getString("runtimePermissionError", "").isEmpty())) {
                lastRuntimePermissionError = "";
                prefs.edit()
                    .remove("runtimePermissionError")
                    .remove("runtimePermissionErrorCode")
                    .putString("lastEvent", "Permissões do observador GTO restauradas")
                    .apply();
                updateNotification();
            }
            return true;
        }

        String code = !overlayOk ? "OVERLAY_REVOKED" : "USAGE_ACCESS_REVOKED";
        String message = !overlayOk
            ? "Permissão do botão flutuante foi desativada pelo Android."
            : "Permissão de acesso de uso foi desativada pelo Android.";
        if (!message.equals(lastRuntimePermissionError)) {
            lastRuntimePermissionError = message;
            prefs.edit()
                .putString("runtimePermissionError", message)
                .putString("runtimePermissionErrorCode", code)
                .putString("lastEvent", message)
                .apply();
            updateNotification();
        }
        foregroundPackage = "";
        if (gtoForeground || bubbleView != null || menuView != null || statusChipView != null
            || freightTouchPulseView != null) {
            gtoForeground = false;
            nonGtoForegroundSince = 0L;
            prefs.edit()
                .putBoolean("gtoForeground", false)
                .putBoolean("touchCaptureNeeded", false)
                .putString("foregroundPackage", "")
                .apply();
            // App switching must not destroy the primary control window. Only transient
            // touch/status surfaces are suspended; the bubble and capture session remain
            // available for immediate return to GTO.
            hideTransientOverlaysKeepBubble();
        }
        return false;
    }

    private boolean isFreightReviewPending() {
        String confirmationStatus = prefs == null ? "" : prefs.getString("selectionConfirmationStatus", "");
        boolean routeStatus = "ROUTE_SELECTION_REQUIRED".equals(confirmationStatus)
            || "ROUTE_SELECTION_READY".equals(confirmationStatus);
        boolean pending = STATE_CONFIRMING_FREIGHT.equals(getTripState())
            && "CONFIRMED".equals(prefs == null ? "" : prefs.getString("selectionIdentityStatus", ""))
            && ("REVIEW_REQUIRED".equals(confirmationStatus) || routeStatus);
        if (pending && routeStatus) return true;
        if (pending && GtoFreightReviewPolicy.DESTINATION_COMPANY.equals(prefs.getString("reviewRequiredField", ""))) {
            // HF14 migration: destinationCompany was incorrectly made driver-required in
            // HF12/HF13. Recompute the next genuinely required field without losing the
            // selected row or any already-read metadata.
            FreightOption current = freightReviewFromPrefs();
            String next = firstReviewField(current);
            prefs.edit()
                .putString("reviewRequiredField", next)
                .putString("lastEvent", next.isEmpty()
                    ? "Empresa de destino opcional · concluindo confirmação do frete"
                    : "Empresa de destino opcional · revisando somente o dado necessário")
                .apply();
            if (next.isEmpty()) {
                mainHandler.post(() -> commitReviewedFreight(current));
                return false;
            }
        }
        return pending;
    }

    private boolean isResultTrackingState(String state) {
        // HF34: result recognition is a continuous screen state, not a one-shot edge.
        // RESULT_DETECTED/AWAITING_BONUS must keep receiving semantic OCR so a subsequent
        // Receber, ADS/bonus, gameplay return or jobs-list boundary is resolved in real time.
        return STATE_TRIP_IN_PROGRESS.equals(state)
            || STATE_RESULT_DETECTED.equals(state)
            || STATE_AWAITING_BONUS.equals(state)
            || (STATE_CONFIRMING_FREIGHT.equals(state) && isFreightReviewPending());
    }

    private boolean resultActionCanBeObserved(String state) {
        if (isTerminalCompletionCommittedForCurrentSession()) return false;
        if (STATE_RESULT_DETECTED.equals(state) || STATE_AWAITING_BONUS.equals(state)) return true;
        return STATE_CONFIRMING_FREIGHT.equals(state)
            && isFreightReviewPending()
            && ("RESULT_SCREEN".equals(prefs.getString("completionStatus", ""))
                || prefs.getBoolean("pendingResultDuringFreightReview", false));
    }

    private boolean captureIsNeededForCurrentState() {
        // HF33: capture ownership belongs to GTO Observe, never to a trip-state enum.
        // The previous state-gated implementation created a circular blind spot: IDLE/
        // CANCELLED expected the freight-list detector to bootstrap WAITING_FREIGHT, but
        // those same states disabled capture/recognition before the detector could see it.
        // Once Observe is enabled, the MediaProjection pipeline remains eligible for every
        // GTO state; the reducer below decides whether recognized pixels may mutate a trip.
        return prefs != null && prefs.getBoolean("enabled", false);
    }

    private void maybeNotifyProjectionReauthorization() {
        if (projectionActive || projectionPermissionInFlight || projectionSurfacePending || !captureIsNeededForCurrentState()) return;
        if (!prefs.getBoolean("projectionReauthRequired", false)) return;
        if (prefs.getBoolean("projectionReauthNoticeShown", false)) return;
        boolean autoAllowed = prefs.getBoolean("projectionReauthAutoAllowed", true);
        prefs.edit()
            .putBoolean("projectionReauthNoticeShown", true)
            .putString("lastEvent", autoAllowed
                ? "Leitura encerrada pelo Android · renovação automática preparada"
                : "Leitura da tela precisa de nova autorização do motorista")
            .apply();
        showStatusChip(autoAllowed
            ? "A leitura foi interrompida pelo Android. O NVU vai reabrir a confirmação automaticamente."
            : "A leitura foi recusada. Abra a bolinha NVU quando quiser autorizar novamente.", 4800L);
        updateNotification();
    }

    private boolean hasVerifiedGtoProjectionBridge() {
        boolean packageMatchesGto = GTO_PACKAGE.equals(foregroundPackage);
        boolean packageUnknown = foregroundPackage == null || foregroundPackage.isEmpty();
        boolean packageIsNvu = getPackageName().equals(foregroundPackage);
        return GtoProjectionForegroundBridgePolicy.allow(
            projectionVerifiedGtoBridgeActive,
            transientForegroundSurfaceActive,
            packageMatchesGto,
            packageUnknown,
            packageIsNvu,
            nvuMainActivityForeground
        );
    }


    private boolean hasTrustedGtoContextForProjectionRecovery(long now) {
        if (transientForegroundSurfaceActive) return false;
        // Exact UsageStats evidence from GTO is stronger than a stale MainActivity latch.
        if (GTO_PACKAGE.equals(foregroundPackage)) return true;
        if (nvuMainActivityForeground) return false;
        boolean visualFresh = lastVisualGtoForegroundEvidenceAt > 0L
            && now >= lastVisualGtoForegroundEvidenceAt
            && now - lastVisualGtoForegroundEvidenceAt <= VISUAL_GTO_EVIDENCE_FRESH_MS;
        return visualFresh || hasVerifiedGtoProjectionBridge();
    }

    private void ensureProjectionAuthorizationIfNeeded(long now) {
        if (!prefs.getBoolean("projectionReauthRequired", false) || !captureIsNeededForCurrentState()) return;
        maybeNotifyProjectionReauthorization();

        DisplayMetrics metrics = realDisplayMetrics();
        boolean trustedGtoContext = hasTrustedGtoContextForProjectionRecovery(now);
        boolean exactGtoPackage = GTO_PACKAGE.equals(foregroundPackage);
        boolean landscape = metrics.widthPixels > metrics.heightPixels && metrics.heightPixels > 0;
        boolean bubbleAttached = bubbleView != null && bubbleView.isAttachedToWindow();
        boolean autoAllowed = prefs.getBoolean("projectionReauthAutoAllowed", true);
        if (!GtoProjectionRecoveryPolicy.shouldAutoRequest(
            true,
            autoAllowed,
            trustedGtoContext,
            exactGtoPackage,
            landscape,
            bubbleAttached,
            true,
            projectionActive,
            projectionSurfacePending,
            projectionPermissionInFlight,
            now,
            lastProjectionAutoReauthAt,
            PROJECTION_AUTO_REAUTH_COOLDOWN_MS
        )) return;

        lastProjectionAutoReauthAt = now;
        prefs.edit()
            .putLong("projectionAutoReauthRequestedAt", now)
            .putString("lastEvent", "Detecção indisponível · solicitando nova autorização automaticamente")
            .apply();
        announceDriverStage(
            "CAPTURE_REAUTH_REQUIRED",
            "A leitura da tela precisa ser reativada. Confirme a autorização do Android.",
            4200L,
            true
        );
        launchProjectionPermissionActivityOnlyWhenGtoLandscape("AUTO_REAUTH_AFTER_CAPTURE_LOSS");
    }

    private void escalateProjectionToFreshAuthorization(String reason) {
        if (destroying || !running || !captureIsNeededForCurrentState()) return;
        String safeReason = reason == null || reason.trim().isEmpty()
            ? "Captura permaneceu sem quadros após recuperação da superfície"
            : reason.trim();
        stopProjection();
        projectionStatus = "REAUTH_REQUIRED_AFTER_STALL";
        prefs.edit()
            .putString("projectionStatus", projectionStatus)
            .putBoolean("projectionReauthRequired", true)
            .putBoolean("projectionReauthAutoAllowed", true)
            .putBoolean("projectionReauthNoticeShown", false)
            .putString("projectionError", safeReason)
            .putString("captureReadiness", "REAUTH_REQUIRED")
            .putBoolean("captureReadyForAnalysis", false)
            .putString("lastEvent", safeReason + " · solicitando nova autorização")
            .apply();
        updateNotification();
        if (gtoForeground) {
            mainHandler.postDelayed(() -> ensureProjectionAuthorizationIfNeeded(System.currentTimeMillis()), 320L);
        }
    }

    private void reconcileProjectionPermissionLifecycle(long now) {
        // A real bound/active MediaProjection is authoritative. If a stale UI latch
        // survived a lifecycle edge, clear only the latch; never discard the grant.
        if (projectionActive || projectionSurfacePending || mediaProjection != null) {
            if (projectionPermissionInFlight) {
                projectionPermissionInFlight = false;
                prefs.edit()
                    .putBoolean("projectionPermissionInFlight", false)
                    .putString("lastEvent", projectionActive
                        ? "Compartilhamento ativo · autorização confirmada"
                        : "Compartilhamento validado · preparando captura no GTO")
                    .apply();
                if (menuView != null) mainHandler.post(this::refreshMenuContents);
            }
            return;
        }
        if (!projectionPermissionInFlight) return;

        long requestAt = Math.max(
            prefs.getLong("projectionConsentGtoVerifiedAt", 0L),
            prefs.getLong("projectionConsentVisibleAt", 0L)
        );
        long resultAt = prefs.getLong("projectionConsentResultAt", 0L);
        if (resultAt > 0L && resultAt >= requestAt) {
            // HF30: RESULT_OK is not a failure just because the service Intent has not
            // reached onStartCommand yet. First rescue the staged in-process grant and give
            // the foreground service a bounded dispatch window. Only after that window do
            // we arm a fresh Android request, automatically, while preserving the trip.
            bindStagedProjectionGrantIfNeeded(resultAt);
            if (projectionActive || projectionSurfacePending || mediaProjection != null) return;
            if (now >= resultAt && now - resultAt < PROJECTION_GRANT_DISPATCH_GRACE_MS) return;
            projectionPermissionInFlight = false;
            projectionStatus = "CONSENT_RESULT_UNBOUND";
            prefs.edit()
                .putBoolean("projectionPermissionInFlight", false)
                .putString("projectionStatus", projectionStatus)
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", true)
                .putBoolean("projectionReauthNoticeShown", false)
                .putString("projectionError", "O Android aceitou o compartilhamento, mas o token não chegou ao serviço dentro da janela de vínculo.")
                .putString("lastEvent", "Resultado de autorização sem vínculo · reativação automática armada")
                .apply();
            if (menuView != null) mainHandler.post(this::refreshMenuContents);
            mainHandler.postDelayed(() -> ensureProjectionAuthorizationIfNeeded(System.currentTimeMillis()), 220L);
            return;
        }

        long consentVisibleAt = prefs.getLong("projectionConsentVisibleAt", 0L);
        boolean returnedToTrustedGto = hasTrustedGtoContextForProjectionRecovery(now);
        if (resultAt <= 0L
            && consentVisibleAt > 0L
            && now >= consentVisibleAt
            && now - consentVisibleAt >= PROJECTION_PERMISSION_RETURN_WITHOUT_RESULT_GRACE_MS
            && returnedToTrustedGto
            && !transientForegroundSurfaceActive) {
            // Some OEMs dismiss the Android consent UI after Share but lose the Activity
            // callback. Once GTO is visibly back and no system permission surface remains,
            // waiting 45 seconds only strands the observer. Unlock and reopen consent.
            projectionPermissionInFlight = false;
            projectionStatus = "CONSENT_RESULT_LOST_AFTER_GTO_RETURN";
            prefs.edit()
                .putBoolean("projectionPermissionInFlight", false)
                .putString("projectionStatus", projectionStatus)
                .putBoolean("projectionReauthRequired", true)
                .putBoolean("projectionReauthAutoAllowed", true)
                .putBoolean("projectionReauthNoticeShown", false)
                .putString("projectionError", "A confirmação do Android fechou sem entregar o resultado ao observador.")
                .putString("lastEvent", "Confirmação fechou sem callback · nova tentativa automática armada")
                .apply();
            if (menuView != null) mainHandler.post(this::refreshMenuContents);
            mainHandler.postDelayed(() -> ensureProjectionAuthorizationIfNeeded(System.currentTimeMillis()), 220L);
            return;
        }

        if (requestAt <= 0L || now < requestAt || now - requestAt < PROJECTION_PERMISSION_RESULT_WATCHDOG_MS) return;
        projectionPermissionInFlight = false;
        projectionStatus = "CONSENT_RESULT_TIMEOUT";
        prefs.edit()
            .putBoolean("projectionPermissionInFlight", false)
            .putString("projectionStatus", projectionStatus)
            .putBoolean("projectionReauthRequired", true)
            .putBoolean("projectionReauthAutoAllowed", true)
            .putBoolean("projectionReauthNoticeShown", false)
            .putString("projectionError", "A tela de autorização não devolveu um resultado ao NVU dentro do tempo esperado.")
            .putString("lastEvent", "Autorização do Android sem retorno · fluxo desbloqueado com segurança")
            .apply();
        if (menuView != null) mainHandler.post(this::refreshMenuContents);
    }

    private boolean isTransientForegroundEvent(String packageName, String className) {
        if (packageName == null) return true;
        if (getPackageName().equals(packageName)
            && className != null
            && className.endsWith("GtoProjectionPermissionActivity")) {
            return true;
        }

        // System UI/permission surfaces can temporarily emit a foreground UsageEvent
        // while GTO remains the actual task underneath. The old implementation ignored
        // them only during the projection dialog, which made the bubble disappear on
        // some OEMs after notification shade/game-system overlays. Never let these
        // transient system surfaces replace the last real application foreground owner.
        String p = packageName.toLowerCase(Locale.ROOT);
        if ("android".equals(p)
            || "com.android.systemui".equals(p)
            || p.contains("permissioncontroller")
            || p.contains("packageinstaller")
            || p.contains("gametime")
            || p.contains("gameassistant")
            || p.contains("gamebooster")
            || p.contains("gameoverlay")) {
            return true;
        }
        return false;
    }

    private boolean hasUsageStatsAccess() {
        return hasUsageStatsAccess(this);
    }

    private void createNotificationChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O || notificationManager == null) return;
        NotificationChannel channel = new NotificationChannel(
            CHANNEL_ID,
            "Observador GTO",
            NotificationManager.IMPORTANCE_LOW
        );
        channel.setDescription("Mantém o botão NVU disponível durante o Global Truck Online.");
        notificationManager.createNotificationChannel(channel);
    }

    private Notification buildNotification() {
        Intent openApp = new Intent(this, MainActivity.class)
            .addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP);
        PendingIntent contentIntent = PendingIntent.getActivity(
            this,
            4608,
            openApp,
            PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE
        );

        Intent stopIntent = new Intent(this, GtoObserverService.class).setAction(ACTION_STOP);
        PendingIntent stopPending = PendingIntent.getService(
            this,
            4609,
            stopIntent,
            PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE
        );

        return new NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.mipmap.ic_launcher)
            .setContentTitle("NVU · Observador GTO")
            .setContentText(notificationText())
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setContentIntent(contentIntent)
            .addAction(0, "Parar", stopPending)
            .build();
    }

    private String notificationText() {
        String runtimeError = prefs == null ? "" : prefs.getString("runtimePermissionError", "");
        if (!runtimeError.isEmpty()) return "Ação necessária · revise as permissões do GTO";
        if (prefs != null && prefs.getBoolean("projectionReauthRequired", false) && captureIsNeededForCurrentState()) {
            return prefs.getBoolean("projectionReauthAutoAllowed", true)
                ? "Reconectando leitura da tela automaticamente"
                : "Ação necessária · autorize novamente a leitura da tela";
        }
        String state = getTripState();
        // Lifecycle describes where the observer is, not which operational stage is
        // active. Never let a stale/background label hide a recoverable trip state: the
        // driver must still see selection, confirmation, completion and sync progress.
        if (prefs != null && GtoObserverLifecyclePolicy.isBackgroundObserverActive(
            prefs.getString("observerLifecycleStatus", "")
        ) && !isRecoverableActiveState(state) && !STATE_RESULT_CONFIRMED.equals(state)) {
            return "Observador ativo · aguardando o retorno do GTO";
        }
        if (STATE_WAITING_FREIGHT.equals(state)
            && "FAILED".equals(prefs.getString("selectionConfirmationStatus", ""))) {
            return "Frete não confirmado · abra a bolinha NVU";
        }
        if (STATE_WAITING_FREIGHT.equals(state)) {
            if (isVisualFreightContextConfirmed(System.currentTimeMillis())) {
                return "Selecione um trabalho";
            }
            if (prefs.getBoolean("pausePromptVisible", pausePromptVisible)) {
                return PAUSE_RECOVERY_PROMPT_MESSAGE;
            }
            if (prefs.getBoolean("pauseScreenDetected", pauseScreenDetectedAt > 0L)) {
                return "Pause detectado · lendo Carga, Origem e Destino…";
            }
            return "Etapa 1/4 · escolha seu frete";
        }
        if (STATE_CONFIRMING_FREIGHT.equals(state)) {
            if (isFreightReviewPending()) {
                return "Frete selecionado · revise " + reviewFieldLabel(prefs.getString("reviewRequiredField", ""));
            }
            return "Etapa 1/4 · confirmando frete…";
        }
        if (STATE_TRIP_STARTED.equals(state)) return "Viagem iniciada · validando ACEITAR + KM…";
        if (STATE_TRIP_IN_PROGRESS.equals(state)) return "Etapa 2/4 · viagem em andamento";
        if (STATE_RESULT_DETECTED.equals(state) || STATE_AWAITING_BONUS.equals(state)) return "Viagem concluída · registro automático em andamento";
        if (STATE_REJECTED_BONUS.equals(state)) return "Última viagem recusada por bônus";
        if (STATE_RESULT_CONFIRMED.equals(state)) {
            String syncStatus = prefs.getString("gtoTripSyncStatus", "");
            if (GtoAutoTripSync.STATUS_SYNCED.equals(syncStatus)) return "Viagem registrada automaticamente";
            if (GtoAutoTripSync.STATUS_REJECTED.equals(syncStatus)) return "Viagem concluída · registro recusado";
            return "Etapa 4/4 · enviando viagem para a NVU";
        }
        return "Botão flutuante pronto para o GTO";
    }

    private void startForegroundForTypes(boolean includeProjection) {
        int serviceTypes = 0;
        if (includeProjection && Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            serviceTypes |= ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
            serviceTypes |= ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE;
        }
        ServiceCompat.startForeground(this, NOTIFICATION_ID, buildNotification(), serviceTypes);
    }

    private void updateNotification() {
        if (notificationManager == null) return;
        try {
            notificationManager.notify(NOTIFICATION_ID, buildNotification());
            if (prefs != null) prefs.edit().remove("notificationError").apply();
        } catch (Exception ex) {
            if (prefs != null) {
                prefs.edit()
                    .putString("notificationError", describeError(ex))
                    .putLong("notificationErrorAt", System.currentTimeMillis())
                    .putString("lastEvent", "Falha ao atualizar notificação do observador GTO")
                    .apply();
            }
        }
    }

    private void resetBubbleLandscapeGeometryStability() {
        bubbleLandscapeStableSince = 0L;
        bubbleLandscapeStableWidth = 0;
        bubbleLandscapeStableHeight = 0;
    }

    private boolean isBubbleLandscapeGeometryStable(long now) {
        DisplayMetrics metrics = realDisplayMetrics();
        int width = metrics.widthPixels;
        int height = metrics.heightPixels;
        if (width <= 0 || height <= 0 || width <= height) {
            resetBubbleLandscapeGeometryStability();
            return false;
        }
        if (bubbleLandscapeStableWidth != width || bubbleLandscapeStableHeight != height) {
            bubbleLandscapeStableWidth = width;
            bubbleLandscapeStableHeight = height;
            bubbleLandscapeStableSince = now;
            return false;
        }
        return bubbleLandscapeStableSince > 0L
            && now >= bubbleLandscapeStableSince
            && now - bubbleLandscapeStableSince >= BUBBLE_LAYOUT_LANDSCAPE_SETTLE_MS;
    }

    private int bubbleSafeMaxX(DisplayMetrics metrics, int bubbleWidth) {
        int safeLeft = dp(8);
        return Math.min(
            Math.max(safeLeft, metrics.widthPixels - bubbleWidth - dp(8)),
            Math.max(safeLeft, freightOverlaySafeRight(metrics) - bubbleWidth - dp(8))
        );
    }

    private int bubbleSafeMaxY(DisplayMetrics metrics, int bubbleHeight) {
        int safeTop = safeTopInsetPx() + dp(8);
        int safeBottom = safeBottomInsetPx() + dp(8);
        return Math.max(safeTop, metrics.heightPixels - safeBottom - bubbleHeight);
    }

    private void persistPreferredGtoBubblePosition(
        DisplayMetrics metrics,
        int bubbleWidth,
        int bubbleHeight,
        String reason
    ) {
        if (prefs == null || bubbleParams == null || metrics == null) return;
        if (!gtoForeground || metrics.widthPixels <= metrics.heightPixels) return;
        int safeLeft = dp(8);
        int safeTop = safeTopInsetPx() + dp(8);
        int maxX = bubbleSafeMaxX(metrics, bubbleWidth);
        int maxY = bubbleSafeMaxY(metrics, bubbleHeight);
        int x = clamp(bubbleParams.x, safeLeft, maxX);
        int y = clamp(bubbleParams.y, safeTop, maxY);
        bubbleParams.x = x;
        bubbleParams.y = y;
        int xNorm = GtoOverlayLayoutPolicy.normalizedPosition(
            x, safeLeft, maxX, BUBBLE_POSITION_SCALE
        );
        int yNorm = GtoOverlayLayoutPolicy.normalizedPosition(
            y, safeTop, maxY, BUBBLE_POSITION_SCALE
        );
        SharedPreferences.Editor editor = prefs.edit()
            // Legacy pixel keys remain for diagnostics/backward compatibility, but HF56
            // restores from the normalized GTO-only anchor on future launches.
            .putInt("bubbleX", bubbleParams.x).putInt("bubbleY", bubbleParams.y)
            .putInt("bubbleGtoXNorm", xNorm)
            .putInt("bubbleGtoYNorm", yNorm)
            .putInt("bubbleGtoPositionDisplayWidth", metrics.widthPixels)
            .putInt("bubbleGtoPositionDisplayHeight", metrics.heightPixels)
            .putInt("bubbleGtoPositionVersion", 1)
            .putLong("bubbleGtoPositionSavedAt", System.currentTimeMillis());
        if (reason != null && !reason.isEmpty()) editor.putString("bubbleGtoPositionReason", reason);
        editor.apply();
    }

    private boolean hasExplicitUserGtoBubblePosition() {
        return prefs != null
            && "USER_DRAG_GTO_LANDSCAPE".equals(
                prefs.getString("bubbleGtoPositionReason", "")
            );
    }

    private void applyInitialGtoBubblePosition(DisplayMetrics metrics, int bubbleWidth, int bubbleHeight) {
        int safeLeft = dp(8);
        int safeTop = safeTopInsetPx() + dp(8);
        int maxX = bubbleSafeMaxX(metrics, bubbleWidth);
        int maxY = bubbleSafeMaxY(metrics, bubbleHeight);

        // Every attach starts at the visual reference anchor. A saved user position is
        // intentionally not restored here; the startup timer below prevents a stale or
        // historical coordinate from replacing the reference before the UI is visible.
        bubbleParams.x = GtoOverlayLayoutPolicy.referenceTopX(
            metrics.widthPixels, bubbleWidth, safeLeft, maxX
        );
        bubbleParams.y = GtoOverlayLayoutPolicy.referenceTopY(
            metrics.heightPixels, safeTop, maxY
        );
        bubbleLayoutDisplayWidth = metrics.widthPixels;
        bubbleLayoutDisplayHeight = metrics.heightPixels;
        bubbleStartupAnchorAt = System.currentTimeMillis();
        scheduleBubbleStartupRestore(bubbleWidth, bubbleHeight);
    }

    private void scheduleBubbleStartupRestore(int bubbleWidth, int bubbleHeight) {
        cancelBubbleStartupRestore();
        if (!hasExplicitUserGtoBubblePosition() || mainHandler == null) return;
        final long startupAt = bubbleStartupAnchorAt;
        bubbleStartupRestoreRunnable = new Runnable() {
            @Override public void run() {
                if (bubbleStartupAnchorAt != startupAt
                    || bubbleView == null
                    || bubbleParams == null
                    || !bubbleView.isAttachedToWindow()) {
                    return;
                }
                long now = System.currentTimeMillis();
                if (!GtoOverlayLayoutPolicy.shouldRestoreSavedPositionAfterStartup(
                    now, startupAt, hasExplicitUserGtoBubblePosition()
                )) {
                    mainHandler.postDelayed(this, GtoOverlayLayoutPolicy.STARTUP_REFERENCE_HOLD_MS);
                    return;
                }
                DisplayMetrics currentMetrics = realDisplayMetrics();
                if (bubbleGestureActive
                    || !gtoForeground
                    || currentMetrics.widthPixels <= currentMetrics.heightPixels) {
                    mainHandler.postDelayed(this, 250L);
                    return;
                }
                rebaseBubbleLayoutForCurrentDisplay(true, "STARTUP_SAVED_POSITION_RESTORE");
                bubbleStartupRestoreRunnable = null;
            }
        };
        mainHandler.postDelayed(
            bubbleStartupRestoreRunnable,
            GtoOverlayLayoutPolicy.STARTUP_REFERENCE_HOLD_MS
        );
    }

    private void cancelBubbleStartupRestore() {
        if (mainHandler != null && bubbleStartupRestoreRunnable != null) {
            mainHandler.removeCallbacks(bubbleStartupRestoreRunnable);
        }
        bubbleStartupRestoreRunnable = null;
    }

    private void resetBubbleStartupRestoreState() {
        cancelBubbleStartupRestore();
        bubbleStartupAnchorAt = 0L;
    }

    private boolean rebaseBubbleLayoutForCurrentDisplay(boolean restorePreferred, String reason) {
        if (bubbleView == null || bubbleParams == null || windowManager == null) return false;
        DisplayMetrics metrics = realDisplayMetrics();
        if (metrics.widthPixels <= 0 || metrics.heightPixels <= 0) return false;
        int bubbleWidth = bubbleView.getWidth() > 0 ? bubbleView.getWidth() : dp(69);
        int bubbleHeight = bubbleView.getHeight() > 0 ? bubbleView.getHeight() : dp(56);
        int safeLeft = dp(8);
        int safeTop = safeTopInsetPx() + dp(8);
        int maxX = bubbleSafeMaxX(metrics, bubbleWidth);
        int maxY = bubbleSafeMaxY(metrics, bubbleHeight);

        int targetX = clamp(bubbleParams.x, safeLeft, maxX);
        int targetY = clamp(bubbleParams.y, safeTop, maxY);
        if (restorePreferred
            && metrics.widthPixels > metrics.heightPixels
            && hasExplicitUserGtoBubblePosition()
            && prefs.contains("bubbleGtoXNorm")
            && prefs.contains("bubbleGtoYNorm")
            && GtoOverlayLayoutPolicy.shouldRestoreSavedPositionAfterStartup(
                System.currentTimeMillis(),
                bubbleStartupAnchorAt,
                true
            )) {
            targetX = GtoOverlayLayoutPolicy.positionFromNormalized(
                prefs.getInt("bubbleGtoXNorm", 0), safeLeft, maxX, BUBBLE_POSITION_SCALE
            );
            targetY = GtoOverlayLayoutPolicy.positionFromNormalized(
                prefs.getInt("bubbleGtoYNorm", 0), safeTop, maxY, BUBBLE_POSITION_SCALE
            );
        }

        boolean changed = targetX != bubbleParams.x || targetY != bubbleParams.y
            || bubbleLayoutDisplayWidth != metrics.widthPixels
            || bubbleLayoutDisplayHeight != metrics.heightPixels;
        bubbleParams.x = targetX;
        bubbleParams.y = targetY;
        bubbleLayoutDisplayWidth = metrics.widthPixels;
        bubbleLayoutDisplayHeight = metrics.heightPixels;
        if (!changed) return true;
        try {
            windowManager.updateViewLayout(bubbleView, bubbleParams);
            if (prefs != null && reason != null && !reason.isEmpty()) {
                prefs.edit()
                    .putLong("bubbleGeometryRebasedAt", System.currentTimeMillis())
                    .putString("bubbleGeometryRebaseReason", reason)
                    .apply();
            }
            return true;
        } catch (Exception ex) {
            recordOverlayFailure(ex);
            return false;
        }
    }

    private void reconcileBubbleForStableGtoGeometry(long now) {
        if (bubbleView == null || !bubbleView.isAttachedToWindow() || bubbleGestureActive) return;
        if (!isBubbleLandscapeGeometryStable(now)) return;
        DisplayMetrics metrics = realDisplayMetrics();
        int bubbleWidth = bubbleView.getWidth() > 0 ? bubbleView.getWidth() : dp(69);
        int bubbleHeight = bubbleView.getHeight() > 0 ? bubbleView.getHeight() : dp(56);
        boolean displayChanged = bubbleLayoutDisplayWidth != metrics.widthPixels
            || bubbleLayoutDisplayHeight != metrics.heightPixels;
        int safeLeft = dp(8);
        int safeTop = safeTopInsetPx() + dp(8);
        int maxX = bubbleSafeMaxX(metrics, bubbleWidth);
        int maxY = bubbleSafeMaxY(metrics, bubbleHeight);
        boolean outOfBounds = !GtoOverlayLayoutPolicy.isInsideSafeRange(bubbleParams.x, safeLeft, maxX)
            || !GtoOverlayLayoutPolicy.isInsideSafeRange(bubbleParams.y, safeTop, maxY);
        if (displayChanged || outOfBounds) {
            rebaseBubbleLayoutForCurrentDisplay(true, "GTO_LANDSCAPE_RESTORED");
        }
    }

    private synchronized void showBubbleIfAllowed() {
        if (bubbleView != null) return;
        long bubbleNow = System.currentTimeMillis();
        lastBubbleAttemptAt = bubbleNow;
        // HF56: bind a fresh WindowManager token only in the final GTO landscape coordinate
        // space. The service still remains alive during rotation; permission launch already
        // waits for this bubble, so no capture/authorization capability is lost.
        if (!isBubbleLandscapeGeometryStable(bubbleNow)) {
            if (prefs != null) prefs.edit()
                .putString("overlaySpawnStatus", "WAITING_STABLE_GTO_LANDSCAPE")
                .putLong("overlaySpawnDeferredAt", bubbleNow)
                .apply();
            return;
        }
        if (windowManager == null) {
            recordOverlayFailure(new IllegalStateException("WindowManager indisponível"));
            return;
        }
        if (!Settings.canDrawOverlays(this)) {
            recordOverlayFailure(new SecurityException("Permissão SYSTEM_ALERT_WINDOW não está ativa"));
            return;
        }
        prefs.edit().putLong("overlayLastAttemptAt", lastBubbleAttemptAt).apply();

        // Restore the compact 1.0.203 control: the updated visual is a small translucent
        // pill, not a large opaque square. Keep the health dot outside the pill so it does
        // not steal the label's touch area on wide GTO displays.
        final int buttonWidth = dp(68);
        final int buttonHeight = dp(32);
        final int healthDotSize = dp(6);
        final int bubbleWidth = buttonWidth;
        bubbleView = new FrameLayout(this);
        bubbleView.setBackgroundColor(Color.TRANSPARENT);
        bubbleView.setElevation(dp(6));

        TextView label = new TextView(this);
        bubbleLabelView = label;
        label.setText("NVU");
        label.setTextColor(Color.WHITE);
        label.setTextSize(12f);
        label.setGravity(Gravity.CENTER);
        label.setTypeface(label.getTypeface(), android.graphics.Typeface.BOLD);
        label.setBackground(makeNvuBubbleBackground(false));
        label.setContentDescription("NVU · tocar para abrir ou fechar os cards da operação");
        FrameLayout.LayoutParams labelParams = new FrameLayout.LayoutParams(buttonWidth, buttonHeight);
        labelParams.gravity = Gravity.START | Gravity.TOP;
        bubbleView.addView(label, labelParams);

        captureHealthDotView = new View(this);
        captureHealthDotView.setBackground(makeRoundedBackground(Color.rgb(82, 88, 96), healthDotSize / 2));
        captureHealthDotView.setAlpha(0.55f);
        FrameLayout.LayoutParams dotParams = new FrameLayout.LayoutParams(healthDotSize, healthDotSize);
        dotParams.gravity = Gravity.END | Gravity.TOP;
        dotParams.setMargins(0, dp(4), dp(4), 0);
        bubbleView.addView(captureHealthDotView, dotParams);
        lastCaptureHealthIndicatorState = null;

        bubbleParams = new WindowManager.LayoutParams(
            bubbleWidth,
            buttonHeight,
            overlayType(),
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
                | WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL
                | WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
            PixelFormat.TRANSLUCENT
        );
        bubbleParams.gravity = Gravity.TOP | Gravity.START;

        DisplayMetrics metrics = realDisplayMetrics();
        // HF56: first install starts at the top; an explicit landscape-GTO drag is restored
        // proportionally on later launches. Legacy coordinates are migrated only when they
        // are already valid in this landscape safe area, never by clamping portrait Y to
        // the bottom edge.
        applyInitialGtoBubblePosition(metrics, bubbleWidth, buttonHeight);
        int bubbleSafeTop = safeTopInsetPx() + dp(8);
        int bubbleSafeBottom = safeBottomInsetPx() + dp(8);
        bubbleParams.y = clamp(
            bubbleParams.y,
            bubbleSafeTop,
            Math.max(bubbleSafeTop, metrics.heightPixels - bubbleSafeBottom - buttonHeight)
        );

        final int touchSlop = Math.max(dp(10), ViewConfiguration.get(this).getScaledTouchSlop());

        bubbleView.setOnTouchListener((view, event) -> {
            final int action = event.getActionMasked();
            final long now = System.currentTimeMillis();
            switch (action) {
                case MotionEvent.ACTION_DOWN:
                    // Rebase before recording the gesture origin. If Android rotated/clamped
                    // the overlay while it stayed attached, drag math now starts from the
                    // actual current safe coordinate on this very first gesture.
                    rebaseBubbleLayoutForCurrentDisplay(false, "POINTER_DOWN_REBASE");
                    beginBubbleGesture(event, now);
                    bubbleLongPressTriggered = false;
                    bubbleDragRemovalArmed = false;
                    if (bubbleLongPressRunnable != null) mainHandler.removeCallbacks(bubbleLongPressRunnable);
                    final long longPressGeneration = bubbleActiveGestureGeneration;
                    bubbleLongPressRunnable = () -> {
                        if (longPressGeneration == bubbleActiveGestureGeneration
                            && bubbleGestureActive && !bubbleDragging) {
                            bubbleLongPressTriggered = true;
                            bubbleDragRemovalArmed = true;
                            openMenu();
                            // A long press may open the card, but it is not required for
                            // removal. The first real move below is the common trigger for
                            // showing the target inside and outside GTO.
                        }
                    };
                    mainHandler.postDelayed(bubbleLongPressRunnable, 520L);
                    return true;
                case MotionEvent.ACTION_MOVE:
                    if (!isBubbleGestureEventCompatible(event)) {
                        cancelBubbleGesture("POINTER_CHANGED", true);
                        return true;
                    }
                    bubbleGestureLastEventAt = now;
                    scheduleBubbleGestureExpiry();
                    float dx = event.getRawX() - bubbleGestureDownRawX;
                    float dy = event.getRawY() - bubbleGestureDownRawY;
                    if (!bubbleDragging && Math.hypot(dx, dy) >= touchSlop) {
                        bubbleDragging = true;
                        if (bubbleLongPressRunnable != null) mainHandler.removeCallbacks(bubbleLongPressRunnable);
                        bubbleLongPressRunnable = null;
                        // Dragging is an explicit user action, so collapsing the menu here
                        // is deterministic. Minor finger jitter never closes it anymore.
                        closeMenu(false);
                    }
                    if (!bubbleDragging) return true;
                    if (GtoBubbleDismissPolicy.shouldShowRemoveTarget(
                        isCurrentBubbleGtoContext(now),
                        bubbleDragging,
                        bubbleGestureActive,
                        bubbleGestureStartedOutsideGto,
                        bubbleDragRemovalArmed
                    )) {
                        showBubbleRemoveTarget(bubbleActiveGestureGeneration);
                    } else {
                        // Starting the gesture over GTO can never become destructive merely
                        // because UsageStats changes while the same finger remains down.
                        hideBubbleRemoveTarget();
                    }
                    DisplayMetrics screen = realDisplayMetrics();
                    int dragSafeLeft = dp(8);
                    int dragMaxX = Math.min(
                        Math.max(dragSafeLeft, screen.widthPixels - bubbleWidth - dp(8)),
                        Math.max(dragSafeLeft, freightOverlaySafeRight(screen) - bubbleWidth - dp(8))
                    );
                    int dragSafeTop = safeTopInsetPx() + dp(8);
                    int dragSafeBottom = safeBottomInsetPx() + dp(8);
                    if (bubbleParams == null || bubbleView == null) {
                        cancelBubbleGesture("BUBBLE_MISSING_DURING_MOVE", true);
                        return true;
                    }
                    bubbleParams.x = clamp(bubbleGestureStartX + Math.round(dx), dragSafeLeft, dragMaxX);
                    bubbleParams.y = clamp(
                        bubbleGestureStartY + Math.round(dy),
                        dragSafeTop,
                        Math.max(dragSafeTop, screen.heightPixels - dragSafeBottom - buttonHeight)
                    );
                    try {
                        windowManager.updateViewLayout(bubbleView, bubbleParams);
                        updateBubbleRemoveTargetHighlight();
                    } catch (Exception ex) {
                        recordOverlayFailure(ex);
                        cancelBubbleGesture("UPDATE_VIEW_FAILURE", true);
                        clearBubbleReferenceAndRemove("UPDATE_VIEW_FAILURE");
                    }
                    return true;
                case MotionEvent.ACTION_UP:
                    boolean pointerMatches = isBubbleGestureActionPointer(event);
                    boolean wasDragging = bubbleDragging;
                    boolean longPress = bubbleLongPressTriggered;
                    long releaseGeneration = bubbleActiveGestureGeneration;
                    boolean geometryInside = isBubbleDroppedOnRemoveTarget(releaseGeneration);
                    boolean stopAllowed = GtoBubbleDismissPolicy.canCommitStop(
                        isCurrentBubbleGtoContext(now),
                        bubbleGestureActive,
                        bubbleDragging,
                        bubbleGestureStartedOutsideGto,
                        bubbleDragRemovalArmed,
                        pointerMatches,
                        bubbleRemoveTargetView != null,
                        bubbleRemoveTargetHighlighted,
                        releaseGeneration != 0L && bubbleRemoveTargetGestureGeneration == releaseGeneration,
                        geometryInside,
                        now,
                        bubbleGestureDownAt,
                        bubbleGestureLastEventAt,
                        BUBBLE_GESTURE_MAX_DURATION_MS,
                        BUBBLE_STOP_RELEASE_FRESH_MS
                    );
                    if (bubbleParams != null) {
                        if (wasDragging && !bubbleGestureStartedOutsideGto) {
                            resetBubbleStartupRestoreState();
                            DisplayMetrics releaseMetrics = realDisplayMetrics();
                            int releaseBubbleWidth = bubbleView != null && bubbleView.getWidth() > 0
                                ? bubbleView.getWidth() : dp(69);
                            int releaseBubbleHeight = bubbleView != null && bubbleView.getHeight() > 0
                                ? bubbleView.getHeight() : buttonHeight;
                            // Only a real drag completed over landscape GTO defines the driver's
                            // preferred GTO position. Portrait/system-app movement is temporary
                            // and can never corrupt the next simulator launch.
                            persistPreferredGtoBubblePosition(
                                releaseMetrics,
                                releaseBubbleWidth,
                                releaseBubbleHeight,
                                "USER_DRAG_GTO_LANDSCAPE"
                            );
                        }
                    }
                    // Invalidate the gesture before any destructive action. A late/replayed
                    // event can no longer reuse the remove target or generation.
                    cancelBubbleGesture("ACTION_UP", false);
                    if (stopAllowed) {
                        stopObserverFromFloatingBubble(releaseGeneration);
                        return true;
                    }
                    if (!wasDragging && bubbleView != null && bubbleParams != null) {
                        // A long press already opened the cards; do not toggle them closed on
                        // ACTION_UP. A short tap keeps the 1.0.203 open/close behavior.
                        if (!longPress) toggleAutomationFromFloatingButton();
                    } else if (bubbleView == null && gtoForeground && Settings.canDrawOverlays(this)) {
                        mainHandler.postDelayed(this::showBubbleIfAllowed, 220L);
                    }
                    return true;
                case MotionEvent.ACTION_CANCEL:
                    cancelBubbleGesture("ACTION_CANCEL", false);
                    return true;
                case MotionEvent.ACTION_POINTER_DOWN:
                case MotionEvent.ACTION_POINTER_UP:
                    // The floating control is intentionally single-touch. Multi-pointer
                    // transitions can alter actionIndex/raw coordinates across OEMs and are
                    // never allowed to authorize a destructive stop.
                    cancelBubbleGesture("MULTI_POINTER", true);
                    return true;
                default:
                    return false;
            }
        });

        boolean bubbleAddedToWindowManager = false;
        FrameLayout bubbleAddedView = bubbleView;
        try {
            int previousFailures = prefs.getInt("overlayFailureCount", 0);
            windowManager.addView(bubbleAddedView, bubbleParams);
            bubbleAddedToWindowManager = true;
            updateNvuBubbleAppearance();
            updateCaptureHealthIndicator(System.currentTimeMillis());
            SharedPreferences.Editor editor = prefs.edit()
                .putBoolean("overlayVisible", true)
                .putBoolean("floatingButtonActivationArmed", false)
                .putLong("floatingButtonActivatedAt", System.currentTimeMillis())
                .putString("overlaySpawnStatus", "ATTACHED_STABLE_LANDSCAPE")
                .remove("overlayError")
                .remove("overlayErrorAt")
                .putInt("overlayFailureCount", 0);
            if (previousFailures > 0) {
                editor.putString("lastEvent", "Botão flutuante restaurado no GTO");
            }
            editor.apply();
        } catch (Exception ex) {
            // `addView()` may already have succeeded when the first health/UI update
            // throws. Never discard only the Java reference: that leaves a visible,
            // immobile orphan while the next retry creates a second movable bubble.
            if (bubbleAddedToWindowManager && bubbleAddedView != null && windowManager != null) {
                try { windowManager.removeViewImmediate(bubbleAddedView); } catch (Exception ignored) {}
            }
            if (bubbleView == bubbleAddedView) bubbleView = null;
            if (bubbleView == null) bubbleLabelView = null;
            if (captureHealthDotView != null && bubbleView == null) captureHealthDotView = null;
            lastCaptureHealthIndicatorState = null;
            bubbleParams = null;
            recordOverlayFailure(ex);
        }
    }

    private boolean hasConfirmedExternalForeground(long now) {
        if (now <= 0L || transientForegroundSurfaceActive || projectionPermissionInFlight) return false;
        String pkg = foregroundPackage == null ? "" : foregroundPackage.trim();
        if (!pkg.isEmpty() && !GTO_PACKAGE.equals(pkg)) return true;
        return lastGtoBackgroundEventAt > lastGtoForegroundEventAt;
    }

    private boolean isCurrentBubbleGtoContext(long now) {
        return gtoForeground
            && !hasConfirmedExternalForeground(now)
            && !transientForegroundSurfaceActive
            && !nvuMainActivityForeground;
    }

    private void beginBubbleGesture(MotionEvent event, long now) {
        cancelBubbleGesture("NEW_ACTION_DOWN", false);
        bubbleGestureGeneration++;
        if (bubbleGestureGeneration <= 0L) bubbleGestureGeneration = 1L;
        bubbleActiveGestureGeneration = bubbleGestureGeneration;
        bubbleGesturePointerId = event.getPointerId(event.getActionIndex());
        bubbleGestureActive = true;
        bubbleDragging = false;
        bubbleDragRemovalArmed = false;
        // HF91: refresh UsageStats at the gesture boundary and use the current owner,
        // not a stale lifecycle latch, to decide whether the destructive target is legal.
        // Capture continuity remains completely independent from this UX decision.
        refreshForegroundPackage();
        bubbleGestureStartedOutsideGto = !isCurrentBubbleGtoContext(now);
        bubbleGestureDownRawX = event.getRawX();
        bubbleGestureDownRawY = event.getRawY();
        bubbleGestureStartX = bubbleParams == null ? 0 : bubbleParams.x;
        bubbleGestureStartY = bubbleParams == null ? 0 : bubbleParams.y;
        bubbleGestureDownAt = now;
        bubbleGestureLastEventAt = now;
        scheduleBubbleGestureExpiry();
    }

    private boolean isBubbleGestureEventCompatible(MotionEvent event) {
        if (!bubbleGestureActive || event == null || event.getPointerCount() != 1) return false;
        return event.getPointerId(0) == bubbleGesturePointerId;
    }

    private boolean isBubbleGestureActionPointer(MotionEvent event) {
        if (!bubbleGestureActive || event == null || event.getPointerCount() < 1) return false;
        int index = event.getActionIndex();
        return index >= 0 && index < event.getPointerCount()
            && event.getPointerId(index) == bubbleGesturePointerId;
    }

    private void scheduleBubbleGestureExpiry() {
        if (mainHandler == null) return;
        if (bubbleGestureExpiryRunnable != null) mainHandler.removeCallbacks(bubbleGestureExpiryRunnable);
        final long generation = bubbleActiveGestureGeneration;
        bubbleGestureExpiryRunnable = () -> {
            if (generation != bubbleActiveGestureGeneration) return;
            expireBubbleGestureIfStale(System.currentTimeMillis());
        };
        mainHandler.postDelayed(bubbleGestureExpiryRunnable, BUBBLE_GESTURE_IDLE_TIMEOUT_MS + 80L);
    }

    private void expireBubbleGestureIfStale(long now) {
        if (!GtoBubbleDismissPolicy.shouldExpireGesture(
            bubbleGestureActive,
            now,
            bubbleGestureDownAt,
            bubbleGestureLastEventAt,
            BUBBLE_GESTURE_MAX_DURATION_MS,
            BUBBLE_GESTURE_IDLE_TIMEOUT_MS
        )) return;
        cancelBubbleGesture("GESTURE_LEASE_EXPIRED", true);
    }

    private void cancelBubbleGesture(String reason, boolean persistDiagnostic) {
        long cancelledGeneration = bubbleActiveGestureGeneration;
        if (mainHandler != null && bubbleLongPressRunnable != null) {
            mainHandler.removeCallbacks(bubbleLongPressRunnable);
        }
        bubbleLongPressRunnable = null;
        bubbleLongPressTriggered = false;
        bubbleGestureActive = false;
        bubbleDragging = false;
        bubbleDragRemovalArmed = false;
        bubbleGestureStartedOutsideGto = false;
        bubbleGesturePointerId = MotionEvent.INVALID_POINTER_ID;
        bubbleActiveGestureGeneration = 0L;
        bubbleGestureDownAt = 0L;
        bubbleGestureLastEventAt = 0L;
        if (mainHandler != null && bubbleGestureExpiryRunnable != null) {
            mainHandler.removeCallbacks(bubbleGestureExpiryRunnable);
        }
        bubbleGestureExpiryRunnable = null;
        hideBubbleRemoveTarget();
        if (persistDiagnostic && prefs != null) {
            prefs.edit()
                .putString("bubbleGestureLastCancelReason", reason == null ? "CANCELLED" : reason)
                .putLong("bubbleGestureLastCancelAt", System.currentTimeMillis())
                .putLong("bubbleGestureLastCancelGeneration", cancelledGeneration)
                .apply();
        }
    }

    private void disarmBubbleStopForCurrentGesture(String reason) {
        if (!bubbleGestureActive) {
            hideBubbleRemoveTarget();
            return;
        }
        boolean wasDestructive = bubbleGestureStartedOutsideGto || bubbleDragRemovalArmed || bubbleRemoveTargetView != null;
        bubbleDragRemovalArmed = false;
        bubbleGestureStartedOutsideGto = false;
        hideBubbleRemoveTarget();
        if (wasDestructive && prefs != null) {
            prefs.edit()
                .putString("bubbleGestureStopDisarmedReason", reason == null ? "CONTEXT_CHANGED" : reason)
                .putLong("bubbleGestureStopDisarmedAt", System.currentTimeMillis())
                .putLong("bubbleGestureStopDisarmedGeneration", bubbleActiveGestureGeneration)
                .apply();
        }
    }

    private void showBubbleRemoveTarget(long gestureGeneration) {
        boolean eligibleOrigin = bubbleDragging;
        if (windowManager == null || bubbleRemoveTargetView != null
            || !bubbleGestureActive || !bubbleDragging || !eligibleOrigin
            || gestureGeneration == 0L || gestureGeneration != bubbleActiveGestureGeneration) return;
        DisplayMetrics screen = realDisplayMetrics();
        final int width = dp(184);
        final int height = dp(52);
        final int bottomMargin = safeBottomInsetPx() + dp(20);

        TextView target = new TextView(this);
        target.setText("Remover e parar NVU");
        target.setTextColor(Color.WHITE);
        target.setTextSize(14f);
        target.setGravity(Gravity.CENTER);
        target.setTypeface(target.getTypeface(), android.graphics.Typeface.BOLD);
        target.setPadding(dp(14), 0, dp(14), 0);
        target.setBackground(makeRoundedBackground(Color.rgb(92, 45, 48), dp(18)));
        target.setElevation(dp(8));

        WindowManager.LayoutParams params = new WindowManager.LayoutParams(
            width,
            height,
            overlayType(),
            WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
                | WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL
                | WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,
            PixelFormat.TRANSLUCENT
        );
        params.gravity = Gravity.TOP | Gravity.START;
        params.x = Math.max(dp(8), (screen.widthPixels - width) / 2);
        params.y = Math.max(
            safeTopInsetPx() + dp(8),
            screen.heightPixels - bottomMargin - height
        );

        try {
            windowManager.addView(target, params);
            bubbleRemoveTargetView = target;
            bubbleRemoveTargetParams = params;
            bubbleRemoveTargetHighlighted = false;
            bubbleRemoveTargetGestureGeneration = gestureGeneration;
            prefs.edit()
                .putBoolean("bubbleRemoveTargetVisible", true)
                .putLong("bubbleRemoveTargetGeneration", gestureGeneration)
                .putString("lastEvent", "Arraste a bolinha até Remover e parar NVU para encerrar o observador")
                .apply();
        } catch (Exception ex) {
            bubbleRemoveTargetView = null;
            bubbleRemoveTargetParams = null;
            bubbleRemoveTargetHighlighted = false;
            bubbleRemoveTargetGestureGeneration = 0L;
            // The optional remove target is not the primary NVU overlay. A failure to
            // attach this helper must never mark the main bubble as unavailable or
            // interfere with capture/observer health.
            if (prefs != null) {
                prefs.edit()
                    .putBoolean("bubbleRemoveTargetVisible", false)
                    .remove("bubbleRemoveTargetGeneration")
                    .putString("bubbleRemoveTargetError", describeError(ex))
                    .putLong("bubbleRemoveTargetErrorAt", System.currentTimeMillis())
                    .apply();
            }
        }
    }

    private void updateBubbleRemoveTargetHighlight() {
        if (bubbleRemoveTargetView == null || bubbleRemoveTargetParams == null || bubbleParams == null || bubbleView == null) return;
        if (!bubbleGestureActive || bubbleRemoveTargetGestureGeneration != bubbleActiveGestureGeneration) {
            hideBubbleRemoveTarget();
            return;
        }
        int bubbleWidth = bubbleView.getWidth() > 0 ? bubbleView.getWidth() : dp(69);
        int bubbleHeight = bubbleView.getHeight() > 0 ? bubbleView.getHeight() : dp(56);
        boolean inside = GtoBubbleDismissPolicy.isDropInside(
            bubbleParams.x, bubbleParams.y, bubbleWidth, bubbleHeight,
            bubbleRemoveTargetParams.x, bubbleRemoveTargetParams.y,
            bubbleRemoveTargetParams.width, bubbleRemoveTargetParams.height
        );
        if (inside == bubbleRemoveTargetHighlighted) return;
        bubbleRemoveTargetHighlighted = inside;
        bubbleRemoveTargetView.setBackground(makeRoundedBackground(
            inside ? Color.rgb(177, 47, 55) : Color.rgb(92, 45, 48),
            dp(18)
        ));
        bubbleRemoveTargetView.setText(inside ? "Solte para remover" : "Remover e parar NVU");
    }

    private boolean isBubbleDroppedOnRemoveTarget(long gestureGeneration) {
        if (bubbleRemoveTargetView == null || bubbleRemoveTargetParams == null
            || bubbleParams == null || bubbleView == null || !bubbleGestureActive
            || gestureGeneration == 0L || bubbleRemoveTargetGestureGeneration != gestureGeneration
            || bubbleActiveGestureGeneration != gestureGeneration) return false;
        int bubbleWidth = bubbleView.getWidth() > 0 ? bubbleView.getWidth() : dp(69);
        int bubbleHeight = bubbleView.getHeight() > 0 ? bubbleView.getHeight() : dp(56);
        return GtoBubbleDismissPolicy.isDropInside(
            bubbleParams.x, bubbleParams.y, bubbleWidth, bubbleHeight,
            bubbleRemoveTargetParams.x, bubbleRemoveTargetParams.y,
            bubbleRemoveTargetParams.width, bubbleRemoveTargetParams.height
        );
    }

    private void hideBubbleRemoveTarget() {
        if (bubbleRemoveTargetView != null && windowManager != null) {
            try { windowManager.removeView(bubbleRemoveTargetView); } catch (Exception ignored) {}
        }
        bubbleRemoveTargetView = null;
        bubbleRemoveTargetParams = null;
        bubbleRemoveTargetHighlighted = false;
        bubbleRemoveTargetGestureGeneration = 0L;
        if (prefs != null) {
            prefs.edit()
                .putBoolean("bubbleRemoveTargetVisible", false)
                .remove("bubbleRemoveTargetGeneration")
                .apply();
        }
    }

    private void stopObserverFromFloatingBubble(long authorizedGestureGeneration) {
        if (authorizedGestureGeneration == 0L) return;
        dispatchObserverStop("Observador GTO encerrado por gesto de remoção validado", authorizedGestureGeneration);
    }


    private void dispatchObserverStop(String event, long gestureGeneration) {
        if (prefs != null) {
            prefs.edit()
                .putString("lastEvent", event == null ? "Observador GTO encerrado" : event)
                .putLong("observerStoppedFromBubbleAt", System.currentTimeMillis())
                .putLong("observerStoppedFromBubbleGesture", gestureGeneration)
                .apply();
        }
        Intent stopIntent = new Intent(this, GtoObserverService.class).setAction(ACTION_STOP);
        try {
            startService(stopIntent);
        } catch (Exception ex) {
            // Both explicit stop paths share the same guarded local fallback. No automatic
            // lifecycle transition can call this method without an explicit user action.
            if (prefs != null) prefs.edit().putBoolean("enabled", false).apply();
            stopProjection();
            removeAllOverlays();
            stopForeground(STOP_FOREGROUND_REMOVE);
            stopSelf();
        }
    }

    private void recordOverlayFailure(Throwable error) {
        int failures = prefs.getInt("overlayFailureCount", 0) + 1;
        String detail = describeError(error);
        String previous = prefs.getString("overlayError", "");
        SharedPreferences.Editor editor = prefs.edit()
            .putBoolean("overlayVisible", false)
            .putString("overlayError", detail)
            .putLong("overlayErrorAt", System.currentTimeMillis())
            .putInt("overlayFailureCount", failures);
        if (failures == 1 || !detail.equals(previous)) {
            editor.putString("lastEvent", "Falha no botão flutuante: " + detail);
        }
        editor.apply();
    }

    private void updateFreightTouchPulseSensor() {
        // HF41: Receber is irreversible in GTO. The 1px passive observer must already
        // exist before RESULT_DETECTED is entered; creating it only after the result OCR
        // left a real main-thread race where a fast tap could close the dialog before the
        // input channel was attached. Keep the non-intercepting observer alive for the
        // whole enabled GTO foreground session. State policy below still decides whether
        // a touch may mutate freight/result data.
        boolean shouldShow = GtoResultActionFlowPolicy.keepPassiveTransportObserver(
            prefs != null && prefs.getBoolean("enabled", false) && !destroying,
            hasAuthorizedCaptureSession(),
            windowManager != null && Settings.canDrawOverlays(this)
        );
        // Listener presence is continuity infrastructure, not action authority. The
        // ACTION_OUTSIDE callback still requires a current visual list/context before it
        // can arm a selection pulse. Keeping it attached across a short rebind prevents
        // the exact race where the second list is detected before transport health turns
        // green and the driver's tap is lost.
        if (shouldShow) showFreightTouchPulseSensor();
        else hideFreightTouchPulseSensor();
    }

    private boolean touchDiagnosticModeEnabled() {
        // Physical-touch telemetry remains persisted/exported, but the diagnostic text
        // overlay is never rendered in the operational GTO surface.
        return false;
    }

    private String beginPhysicalTouchAttempt(MotionEvent event) {
        long now = System.currentTimeMillis();
        outsideTouchCount++;
        String touchAttemptId = "touch-" + now + "-" + outsideTouchCount;
        activePhysicalTouchAttemptId = touchAttemptId;
        activePhysicalTouchAttemptAt = now;
        activePhysicalTouchStage = "ACTION_OUTSIDE_RECEIVED";
        activePhysicalTouchResolvedRow = -1;
        activePhysicalTouchResolutionReason = "PENDING_RESOLUTION";
        float rawX = event == null ? -1f : event.getRawX();
        float rawY = event == null ? -1f : event.getRawY();
        float localX = event == null ? -1f : event.getX();
        float localY = event == null ? -1f : event.getY();
        DisplayMetrics display = realDisplayMetrics();
        int acceptCount = currentTouchButtons().size();
        lastOutsideTouchX = rawX;
        lastOutsideTouchY = rawY;
        lastOutsideAltX = localX;
        lastOutsideAltY = localY;
        lastOutsideTouchAt = now;
        if (prefs != null) {
            prefs.edit()
                .putInt("outsideTouchCount", outsideTouchCount)
                .putString("physicalTouchAttemptId", touchAttemptId)
                .putLong("physicalTouchAttemptAt", now)
                .putString("physicalTouchStage", activePhysicalTouchStage)
                .putBoolean("physicalTouchEventReceived", true)
                .putBoolean("physicalActionOutsideReceived", true)
                .putLong("physicalActionOutsideAt", now)
                .putFloat("physicalTouchRawX", rawX)
                .putFloat("physicalTouchRawY", rawY)
                .putFloat("physicalTouchLocalX", localX)
                .putFloat("physicalTouchLocalY", localY)
                .putInt("physicalTouchDisplayWidth", display.widthPixels)
                .putInt("physicalTouchDisplayHeight", display.heightPixels)
                .putInt("physicalTouchCaptureWidth", captureWidth)
                .putInt("physicalTouchCaptureHeight", captureHeight)
                .putString("physicalTouchCoordinateSpace", "UNRESOLVED")
                .putLong("physicalTouchListGeneration", freightPageGeneration)
                .putLong("physicalTouchFreightPageGeneration", freightPageGeneration)
                .putInt("physicalTouchRowCount", acceptCount)
                .putInt("physicalTouchAcceptRectCount", acceptCount)
                .putInt("physicalTouchResolvedRow", -1)
                .putString("physicalTouchResolutionReason", "PENDING_RESOLUTION")
                .putBoolean("physicalTouchTargetLocked", false)
                .putString("physicalTouchValidationResult", "PENDING")
                .putString("physicalTouchCommitResult", "PENDING")
                .putLong("lastOutsideTouchAt", now)
                .apply();
        }
        recordObserverEvent(
            "TOUCH_EVENT_RECEIVED",
            "touchAttemptId=" + touchAttemptId + " action=ACTION_OUTSIDE"
        );
        recordObserverEvent(
            "ACTION_OUTSIDE_RECEIVED",
            "touchAttemptId=" + touchAttemptId
                + " raw=" + Math.round(rawX) + "," + Math.round(rawY)
                + " local=" + Math.round(localX) + "," + Math.round(localY)
        );
        refreshPhysicalTouchDiagnosticOverlay();
        return touchAttemptId;
    }

    private void updatePhysicalTouchDiagnostic(
        String stage,
        int resolvedRow,
        String coordinateSpace,
        String reason,
        Boolean targetLocked,
        String validationResult,
        String commitResult
    ) {
        if (prefs == null) return;
        if (stage != null && !stage.trim().isEmpty()) activePhysicalTouchStage = stage.trim();
        if (resolvedRow >= 0) activePhysicalTouchResolvedRow = resolvedRow;
        if (reason != null && !reason.trim().isEmpty()) activePhysicalTouchResolutionReason = reason.trim();
        SharedPreferences.Editor editor = prefs.edit()
            .putString("physicalTouchStage", activePhysicalTouchStage)
            .putInt("physicalTouchResolvedRow", activePhysicalTouchResolvedRow)
            .putString("physicalTouchResolutionReason", activePhysicalTouchResolutionReason);
        if (coordinateSpace != null && !coordinateSpace.trim().isEmpty()) {
            editor.putString("physicalTouchCoordinateSpace", coordinateSpace.trim());
        }
        if (targetLocked != null) editor.putBoolean("physicalTouchTargetLocked", targetLocked);
        if (validationResult != null && !validationResult.trim().isEmpty()) {
            editor.putString("physicalTouchValidationResult", validationResult.trim());
        }
        if (commitResult != null && !commitResult.trim().isEmpty()) {
            editor.putString("physicalTouchCommitResult", commitResult.trim());
        }
        editor.apply();
        refreshPhysicalTouchDiagnosticOverlay();
    }

    private void markPhysicalTouchAwaitingForCurrentList(int acceptCount, long now) {
        if (prefs == null || acceptCount <= 0) return;
        long currentGeneration = freightPageGeneration;
        long previousGeneration = prefs.getLong("physicalTouchExpectedGeneration", -1L);
        if (previousGeneration == currentGeneration
            && prefs.getLong("physicalTouchExpectedAt", 0L) > 0L) return;
        prefs.edit()
            .putBoolean("touchDiagnosticMode", false)
            .putLong("physicalTouchExpectedGeneration", currentGeneration)
            .putLong("physicalTouchExpectedAt", now)
            .putString("physicalTouchStage", "WAITING_PHYSICAL_TOUCH")
            .putBoolean("physicalTouchEventReceived", false)
            .putBoolean("physicalActionOutsideReceived", false)
            .putInt("physicalTouchAcceptRectCount", acceptCount)
            .putInt("physicalTouchRowCount", acceptCount)
            .putInt("physicalTouchResolvedRow", -1)
            .putString("physicalTouchResolutionReason", "WAITING_TOUCH")
            .putBoolean("physicalTouchTargetLocked", false)
            .putString("physicalTouchValidationResult", "WAITING")
            .putString("physicalTouchCommitResult", "WAITING")
            .apply();
        refreshPhysicalTouchDiagnosticOverlay();
    }

    private String physicalTouchDiagnosticText() {
        if (prefs == null) return "";
        boolean received = prefs.getBoolean("physicalTouchEventReceived", false);
        boolean outside = prefs.getBoolean("physicalActionOutsideReceived", false);
        int row = prefs.getInt("physicalTouchResolvedRow", -1);
        float rawX = prefs.getFloat("physicalTouchRawX", -1f);
        float rawY = prefs.getFloat("physicalTouchRawY", -1f);
        String space = prefs.getString("physicalTouchCoordinateSpace", "UNRESOLVED");
        int accepts = prefs.getInt("physicalTouchAcceptRectCount", 0);
        boolean locked = prefs.getBoolean("physicalTouchTargetLocked", false);
        String validation = prefs.getString("physicalTouchValidationResult", "WAITING");
        String commit = prefs.getString("physicalTouchCommitResult", "WAITING");
        String reason = prefs.getString("physicalTouchResolutionReason", "WAITING_TOUCH");
        return "DIAGNÓSTICO ACEITAR HF208\n"
            + "SENSOR: " + (prefs.getBoolean("touchPulseSensorVisible", false) ? "READY" : "OFF")
            + " · TOUCH: " + (received ? "YES" : "NO")
            + " · OUTSIDE: " + (outside ? "YES" : "NO") + "\n"
            + "X/Y: " + Math.round(rawX) + "," + Math.round(rawY)
            + " · SPACE: " + space
            + " · ACCEPTS: " + accepts + "\n"
            + "ROW: " + (row >= 0 ? String.valueOf(row) : "NONE")
            + " · TARGET: " + (locked ? "LOCKED" : "WAITING") + "\n"
            + "VALIDATION: " + validation + " · COMMIT: " + commit
            + (row < 0 ? "\nREASON: " + reason : "");
    }

