    private static final class FreightSelectionTransaction {
        final int rowIndex;
        final Bitmap panelFrame;
        final int panelOffsetX;
        final List<Rect> buttons;
        final String source;
        final long touchSequence;
        final String sessionId;
        final String attemptId;
        final long generation;
        final long pageGeneration;
        final FreightOption baselineOption;
        final long createdAt;
        private boolean closed = false;

        FreightSelectionTransaction(
            int rowIndex,
            Bitmap panelFrame,
            int panelOffsetX,
            List<Rect> buttons,
            String source,
            long touchSequence,
            String sessionId,
            String attemptId,
            long generation,
            long pageGeneration,
            FreightOption baselineOption
        ) {
            this.rowIndex = rowIndex;
            this.panelFrame = panelFrame;
            this.panelOffsetX = panelOffsetX;
            this.buttons = buttons;
            this.source = source;
            this.touchSequence = touchSequence;
            this.sessionId = sessionId == null ? "" : sessionId;
            this.attemptId = attemptId == null ? "" : attemptId;
            this.generation = generation;
            this.pageGeneration = pageGeneration;
            this.baselineOption = baselineOption;
            this.createdAt = System.currentTimeMillis();
        }

        void close() {
            if (closed) return;
            closed = true;
            if (panelFrame != null && !panelFrame.isRecycled()) panelFrame.recycle();
        }
    }

    private static class ButtonFrameSample {
        long at;
        final List<Rect> buttons = new ArrayList<>();
        final List<int[]> signatures = new ArrayList<>();
        final List<Float> orangeRatios = new ArrayList<>();

        ButtonFrameSample copy() {
            ButtonFrameSample copy = new ButtonFrameSample();
            copy.at = at;
            for (Rect rect : buttons) copy.buttons.add(new Rect(rect));
            for (int[] signature : signatures) copy.signatures.add(signature == null ? new int[0] : signature.clone());
            copy.orangeRatios.addAll(orangeRatios);
            return copy;
        }
    }

    private static class FreightOption {
        int rowIndex;
        Rect acceptRect;
        int acceptCenterY;
        int rowTop;
        int rowBottom;
        float buttonOrangeBaseline = 0f;
        float lastButtonOrangeRatio = 0f;
        int[] buttonVisualSignature = new int[0];
        String cargo = "";
        String companyRoute = "";
        String originCompany = "";
        String destinationCompany = "";
        String origin = "";
        String destination = "";
        // Accepted-list authority preserved across later Pause rereads. This is
        // intentionally separate from the Pause operational destination field.
        String acceptedListOrigin = "";
        String acceptedListDestination = "";
        float destinationOcrConfidence = 0f;
        String km = "";
        String offeredValue = "";
        String rawText = "";
        boolean acceptTextEvidence = false;
        float dataConfidence = 0f;
        int consensusFrames = 0;
        int cargoVotes = 0;
        int originVotes = 0;
        int originCompanyVotes = 0;
        int destinationCompanyVotes = 0;
        int destinationVotes = 0;
        int kmVotes = 0;
        int valueVotes = 0;
        // Independent evidence from the immutable selected-row snapshot. These flags
        // never choose a row; they only allow a valid field from the already-touched
        // row to stand on its own without manufacturing a second OCR vote.
        boolean cargoSelectedRowEvidence = false;
        // Explicitly marks a List literal independently tied to the selected row and
        // therefore protected from a divergent Pause OCR candidate.
        boolean cargoListSameRowAuthority = false;
        // Explicitly marks the narrow human+geometry direct-promotion path. It is
        // never inferred from a generic OCR vote and is copied with the option.
        boolean directSelectedRowEvidence = false;
        boolean originSelectedRowEvidence = false;
        boolean originCompanySelectedRowEvidence = false;
        boolean destinationCompanySelectedRowEvidence = false;
        boolean destinationSelectedRowEvidence = false;
        boolean kmSelectedRowEvidence = false;
        boolean valueSelectedRowEvidence = false;
        // New contract: cargo/origin/destination are not OCR inputs. Origin and
        // destination are selected from the closed driver-facing route list.
        boolean manualRouteSelectionConfirmed = false;
        // Explicit trusted-source marker for the detailed pause surface. This is
        // intentionally separate from OCR vote counters: it authorizes the pause
        // contract without pretending that one pause frame was two OCR reads.
        boolean pauseMenuEvidence = false;
        // True only after a complete Pause reread passed field and anchor validation.
        // It authorizes same-session durable reconciliation; merely opening Pause does not.
        boolean pauseCorrectionConfirmed = false;
        String originEvidenceSource = "";
        String originCompanyEvidenceSource = "";

        String summary() {
            List<String> parts = new ArrayList<>();
            String visibleOrigin = GtoAcceptedFreightFieldPolicy.acceptedVisibleOrigin(
                acceptedListOrigin, origin, originCompany, pauseMenuEvidence, pauseCorrectionConfirmed
            );
            String visibleDestination = GtoAcceptedFreightFieldPolicy.acceptedVisibleDestination(
                acceptedListDestination, destination, destinationCompany, rawText, companyRoute,
                originCompany, pauseCorrectionConfirmed
            );
            if (!visibleOrigin.isEmpty() && !visibleDestination.isEmpty()) parts.add(visibleOrigin + " → " + visibleDestination);
            else if (!visibleDestination.isEmpty()) parts.add(visibleDestination);
            if (!km.isEmpty()) parts.add(km);
            if (!offeredValue.isEmpty()) parts.add(offeredValue);
            return parts.isEmpty() ? "linha " + (rowIndex + 1) : android.text.TextUtils.join(" · ", parts);
        }
    }

